export default {"file":"vehicle-management.html","title":"Vehicle Management - Schoolix","htmlClass":"","bodyClass":"sx-admin-tool sx-transport-page","body":"\r\n<div class=\"sx-transport-page-busy\" id=\"transportPageBusy\" aria-live=\"polite\" aria-hidden=\"true\">\r\n  <div class=\"sx-transport-busy-card\">\r\n    <div class=\"sx-spinner\" aria-hidden=\"true\"></div>\r\n    <strong id=\"transportBusyTitle\">Loading transport workspace...</strong>\r\n    <p class=\"muted\" id=\"transportBusyText\">Fetching routes, vehicles and live tracking status.</p>\r\n  </div>\r\n</div>\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n    <div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n<div class=\"container\">\r\n    <div class=\"card transport-hero\">\r\n        <div class=\"transport-hero-main\">\r\n            <div>\r\n                <span class=\"transport-hero-kicker\">\r\n                    <svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 21s7-4.6 7-11a7 7 0 1 0-14 0c0 6.4 7 11 7 11Z\"/><circle cx=\"12\" cy=\"10\" r=\"2.5\"/></svg>\r\n                    Transport Control Center\r\n                </span>\r\n                <h1>Vehicles, routes and live bus tracking</h1>\r\n                <p class=\"muted\">Manage fleet records, assign students, save routes, and monitor live GPS from one clean transport workspace.</p>\r\n            </div>\r\n            <div class=\"hero-actions\">\r\n                <button type=\"button\" class=\"btn-primary\" onclick=\"document.getElementById('vehicleFormCard').scrollIntoView({behavior:'smooth',block:'start'})\">Add Vehicle</button>\r\n                <button type=\"button\" class=\"btn-secondary\" onclick=\"document.getElementById('adminLiveMap').scrollIntoView({behavior:'smooth',block:'center'})\">Open Live Map</button>\r\n            </div>\r\n        </div>\r\n        <div class=\"transport-command-panel\">\r\n            <div>\r\n                <div class=\"command-title\">Today at a glance</div>\r\n                <p class=\"muted\">Fleet health, assignments, and route coverage update as records load.</p>\r\n            </div>\r\n            <div class=\"command-grid\">\r\n                <div class=\"command-tile\"><strong id=\"heroActiveVehicles\">0</strong><span>Active fleet</span></div>\r\n                <div class=\"command-tile\"><strong id=\"heroAssignedStudents\">0</strong><span>Assigned students</span></div>\r\n                <div class=\"command-tile\"><strong id=\"heroSavedRoutes\">0</strong><span>Saved routes</span></div>\r\n                <div class=\"command-tile\"><strong id=\"heroLiveVehicles\">0</strong><span>Live vehicles</span></div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"card transport-section\">\r\n        <div class=\"section-heading\">\r\n            <div class=\"section-title-block\">\r\n                <span class=\"icon-tile\" aria-hidden=\"true\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 3v18h18\"/><path d=\"M7 15l4-4 3 3 5-7\"/></svg></span>\r\n                <div>\r\n                    <h2>Overview</h2>\r\n                    <div class=\"section-subtitle\">Fast fleet counts for admin review.</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <div class=\"stats\">\r\n            <div class=\"stat\"><span class=\"stat-icon\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M8 6v6\"/><path d=\"M15 6v6\"/><path d=\"M2 12h19.6\"/><path d=\"M18 18h3s.5-1.7.8-3.2c.1-.7.2-1.4.2-2.1V8a3 3 0 0 0-3-3H5a3 3 0 0 0-3 3v10h3\"/><circle cx=\"7\" cy=\"18\" r=\"2\"/><circle cx=\"16\" cy=\"18\" r=\"2\"/></svg></span><div><strong id=\"totalVehicles\">0</strong><span>Total Vehicles</span></div></div>\r\n            <div class=\"stat\"><span class=\"stat-icon\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M20 6L9 17l-5-5\"/></svg></span><div><strong id=\"activeVehicles\">0</strong><span>Active</span></div></div>\r\n            <div class=\"stat\"><span class=\"stat-icon\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M14.7 6.3a1 1 0 0 0 0 1.4l1.6 1.6a1 1 0 0 0 1.4 0l3.1-3.1a6 6 0 0 1-7.9 7.9l-6.7 6.7a2.1 2.1 0 0 1-3-3l6.7-6.7a6 6 0 0 1 7.9-7.9z\"/></svg></span><div><strong id=\"maintenanceVehicles\">0</strong><span>In Maintenance</span></div></div>\r\n            <div class=\"stat\"><span class=\"stat-icon\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M15 9l-6 6\"/><path d=\"M9 9l6 6\"/></svg></span><div><strong id=\"inactiveVehicles\">0</strong><span>Inactive</span></div></div>\r\n            <div class=\"stat\"><span class=\"stat-icon\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"6\" cy=\"19\" r=\"3\"/><path d=\"M9 19h8.5a3.5 3.5 0 0 0 0-7H8a3 3 0 0 1 0-6h10\"/><circle cx=\"18\" cy=\"5\" r=\"3\"/></svg></span><div><strong id=\"totalRoutes\">0</strong><span>Saved Routes</span></div></div>\r\n            <div class=\"stat\"><span class=\"stat-icon\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg></span><div><strong id=\"totalAssigned\">0</strong><span>Students Assigned</span></div></div>\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"card transport-live-card\">\r\n        <div class=\"section-heading transport-section\" style=\"margin-bottom:0;\">\r\n            <div class=\"section-title-block\">\r\n                <span class=\"icon-tile\" aria-hidden=\"true\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 21s7-4.6 7-11a7 7 0 1 0-14 0c0 6.4 7 11 7 11Z\"/><circle cx=\"12\" cy=\"10\" r=\"2.5\"/></svg></span>\r\n                <div>\r\n                    <h2>Live Tracking Map</h2>\r\n                    <div class=\"section-subtitle\">Active GPS locations appear here through Supabase Realtime and MapLibre.</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <div class=\"live-map-grid\">\r\n            <div class=\"transport-map\" id=\"adminLiveMap\">\r\n              <div class=\"sx-map-fallback\">\r\n                <svg class=\"icon icon-lg\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.8\"><path d=\"M9 4 3 6.5v13L9 17l6 2.5 6-2.5v-13L15 6.5 9 4Z\"/><path d=\"M9 4v13\"/><path d=\"M15 6.5v13\"/></svg>\r\n                <strong>Preparing live map…</strong>\r\n                <span>Vehicle positions load as soon as an active trip streams GPS.</span>\r\n              </div>\r\n            </div>\r\n            <div class=\"live-vehicle-list\" id=\"adminLiveVehicleList\">\r\n                <div class=\"empty\">Live locations will appear when active trips send GPS updates.</div>\r\n            </div>\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"transport-workspace\">\r\n    <div class=\"workspace-column\">\r\n    <div class=\"card transport-section\" id=\"vehicleFormCard\">\r\n        <div class=\"section-heading\">\r\n            <div class=\"section-title-block\">\r\n                <span class=\"icon-tile\" aria-hidden=\"true\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M8 6v6\"/><path d=\"M15 6v6\"/><path d=\"M2 12h19.6\"/><path d=\"M18 18h3s.5-1.7.8-3.2c.1-.7.2-1.4.2-2.1V8a3 3 0 0 0-3-3H5a3 3 0 0 0-3 3v10h3\"/><circle cx=\"7\" cy=\"18\" r=\"2\"/><circle cx=\"16\" cy=\"18\" r=\"2\"/></svg></span>\r\n                <div>\r\n                    <h2 id=\"formTitle\">Add Vehicle</h2>\r\n                    <div class=\"section-subtitle\">Vehicle details, driver info, compliance dates, and assigned route.</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <form id=\"vehicleForm\">\r\n            <div class=\"grid\">\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"vehicleNumber\">Vehicle registration number</label>\r\n                    <input id=\"vehicleNumber\" placeholder=\"e.g. UP32AB1234\" required>\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"vehicleType\">Vehicle type</label>\r\n                    <select id=\"vehicleType\" required>\r\n                        <option value=\"\">Select Type</option>\r\n                        <option value=\"Bus\">Bus</option>\r\n                        <option value=\"Van\">Van</option>\r\n                        <option value=\"Mini Bus\">Mini Bus</option>\r\n                        <option value=\"Other\">Other</option>\r\n                    </select>\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"vehicleModel\">Model / manufacturer</label>\r\n                    <input id=\"vehicleModel\" placeholder=\"e.g. Tata Starbus\">\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"capacity\">Seating capacity</label>\r\n                    <input id=\"capacity\" type=\"number\" min=\"1\" placeholder=\"Number of seats\">\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"driverName\">Driver name</label>\r\n                    <input id=\"driverName\" placeholder=\"Full name\">\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"driverPhone\">Driver phone</label>\r\n                    <input id=\"driverPhone\" placeholder=\"Mobile number\">\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"driverEmail\">Driver login email</label>\r\n                    <input id=\"driverEmail\" type=\"email\" placeholder=\"driver@example.com\" autocomplete=\"username\">\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"driverPassword\">Set driver password</label>\r\n                    <input id=\"driverPassword\" type=\"password\" minlength=\"6\" placeholder=\"Min 6 characters\" autocomplete=\"new-password\">\r\n                    <span class=\"field-hint\">Required only when creating a new driver login.</span>\r\n                </div>\r\n                <div class=\"field-group full-row\">\r\n                    <label class=\"field-label\" for=\"vehicleRouteSelect\">Assign route (optional)</label>\r\n                    <span class=\"field-hint\">Pick a saved route (From - To) or use manual name below.</span>\r\n                    <select id=\"vehicleRouteSelect\"></select>\r\n                </div>\r\n                <div class=\"field-group full-row\">\r\n                    <label class=\"field-label\" for=\"routeName\">Route name / label (manual)</label>\r\n                    <span class=\"field-hint\">Required if no saved route selected.</span>\r\n                    <input id=\"routeName\" placeholder=\"e.g. Route A / Morning North\">\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"permitExpiry\">Permit valid till</label>\r\n                    <input id=\"permitExpiry\" type=\"date\">\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"insuranceExpiry\">Insurance valid till</label>\r\n                    <input id=\"insuranceExpiry\" type=\"date\">\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"fitnessExpiry\">Fitness certificate valid till</label>\r\n                    <input id=\"fitnessExpiry\" type=\"date\">\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"vehicleStatus\">Vehicle status</label>\r\n                    <select id=\"vehicleStatus\" required>\r\n                        <option value=\"active\">Active</option>\r\n                        <option value=\"maintenance\">Maintenance</option>\r\n                        <option value=\"inactive\">Inactive</option>\r\n                    </select>\r\n                </div>\r\n                <div class=\"field-group full-row\">\r\n                    <label class=\"field-label\" for=\"notes\">Notes (optional)</label>\r\n                    <textarea id=\"notes\" rows=\"3\" placeholder=\"Any extra remarks\"></textarea>\r\n                </div>\r\n                <div class=\"full-row\" style=\"display:flex; gap:10px; flex-wrap:wrap;\">\r\n                    <button type=\"submit\" class=\"btn-primary\" id=\"saveBtn\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z\"/><path d=\"M17 21v-8H7v8\"/><path d=\"M7 3v5h8\"/></svg>Save Vehicle</button>\r\n                    <button type=\"button\" class=\"btn-secondary\" onclick=\"resetForm()\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M21 12a9 9 0 1 1-2.64-6.36\"/><path d=\"M21 3v6h-6\"/></svg>Reset</button>\r\n                </div>\r\n            </div>\r\n        </form>\r\n    </div>\r\n    </div>\r\n\r\n    <div class=\"workspace-column\">\r\n    <div class=\"card transport-section\" id=\"routeLookupCard\">\r\n        <div class=\"section-heading\">\r\n            <div class=\"section-title-block\">\r\n                <span class=\"icon-tile\" aria-hidden=\"true\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"M21 21l-4.3-4.3\"/></svg></span>\r\n                <div>\r\n                    <h2>Route lookup</h2>\r\n                    <div class=\"section-subtitle\">Find saved route details quickly.</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <p class=\"muted\">Enter a saved route ID (e.g. RT123456) to load that route's details.</p>\r\n        <div class=\"grid\" style=\"margin-top: 12px; align-items: end;\">\r\n            <div class=\"field-group\">\r\n                <label class=\"field-label\" for=\"routeLookupInput\">Route ID</label>\r\n                <input id=\"routeLookupInput\" placeholder=\"e.g. RT123456\" autocomplete=\"off\">\r\n            </div>\r\n            <button type=\"button\" class=\"btn-primary\" onclick=\"fetchRouteById()\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"M21 21l-4.3-4.3\"/></svg>Fetch route</button>\r\n        </div>\r\n        <div id=\"routeLookupResult\" class=\"route-lookup-box\">\r\n            <p style=\"margin-bottom: 8px;\"><strong>Route ID:</strong> <span class=\"route-id-badge\" id=\"lookupRouteId\"></span></p>\r\n            <p><strong>From:</strong> <span id=\"lookupFrom\"></span></p>\r\n            <div id=\"lookupViaBlock\" style=\"display: none; margin: 8px 0;\">\r\n                <strong>Via (bus stops in order):</strong>\r\n                <ol class=\"via-stops-list\" id=\"lookupViaList\"></ol>\r\n            </div>\r\n            <p><strong>To:</strong> <span id=\"lookupTo\"></span></p>\r\n            <p><strong>Notes:</strong> <span id=\"lookupNotes\"></span></p>\r\n        </div>\r\n    </div>\r\n\r\n    <div class=\"card transport-section\">\r\n        <div class=\"section-heading\">\r\n            <div class=\"section-title-block\">\r\n                <span class=\"icon-tile\" aria-hidden=\"true\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"6\" cy=\"19\" r=\"3\"/><path d=\"M9 19h8.5a3.5 3.5 0 0 0 0-7H8a3 3 0 0 1 0-6h10\"/><circle cx=\"18\" cy=\"5\" r=\"3\"/></svg></span>\r\n                <div>\r\n                    <h2>School routes</h2>\r\n                    <div class=\"section-subtitle\">Build reusable routes and ordered via stops.</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <p class=\"muted\">Save every school route with a clear start and end point.</p>\r\n        <form id=\"routeForm\">\r\n            <div class=\"grid\">\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"routeFrom\">From (start point)</label>\r\n                    <input id=\"routeFrom\" placeholder=\"e.g. School gate / Sector 5\" required>\r\n                </div>\r\n                <div class=\"field-group full-row via-section\">\r\n                    <label class=\"field-label\">Via stops (optional)</label>\r\n                    <span class=\"field-hint\">Bus ya vehicle jahan-jahan rukta hai - order mein add karo.</span>\r\n                    <div id=\"viaStopsContainer\"></div>\r\n                    <button type=\"button\" class=\"btn-success\" style=\"margin-top:10px;\" onclick=\"addViaStopRow()\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 5v14\"/><path d=\"M5 12h14\"/></svg>Add via stop</button>\r\n                </div>\r\n                <div class=\"field-group\">\r\n                    <label class=\"field-label\" for=\"routeTo\">To (end point)</label>\r\n                    <input id=\"routeTo\" placeholder=\"e.g. City bus stand / Village name\" required>\r\n                </div>\r\n                <div class=\"field-group full-row\">\r\n                    <label class=\"field-label\" for=\"routeNotes\">Route notes (optional)</label>\r\n                    <textarea id=\"routeNotes\" rows=\"2\" placeholder=\"Optional details\"></textarea>\r\n                </div>\r\n                <div class=\"full-row\" style=\"display:flex; gap:10px; flex-wrap:wrap;\">\r\n                    <button type=\"submit\" class=\"btn-primary\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z\"/><path d=\"M17 21v-8H7v8\"/><path d=\"M7 3v5h8\"/></svg>Save route</button>\r\n                    <button type=\"button\" class=\"btn-secondary\" onclick=\"resetRouteForm()\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 6h18\"/><path d=\"M8 6V4h8v2\"/><path d=\"M19 6l-1 14H6L5 6\"/></svg>Clear</button>\r\n                </div>\r\n            </div>\r\n        </form>\r\n        <h3 style=\"margin-top: 20px; margin-bottom: 8px; font-size: 1rem;\">All saved routes</h3>\r\n        <div class=\"list\" id=\"routeList\"></div>\r\n    </div>\r\n    </div>\r\n    </div>\r\n\r\n    <div class=\"card transport-section\">\r\n        <div class=\"section-heading\">\r\n            <div class=\"section-title-block\">\r\n                <span class=\"icon-tile\" aria-hidden=\"true\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M8 6h13\"/><path d=\"M8 12h13\"/><path d=\"M8 18h13\"/><path d=\"M3 6h.01\"/><path d=\"M3 12h.01\"/><path d=\"M3 18h.01\"/></svg></span>\r\n                <div>\r\n                    <h2>Vehicle Records</h2>\r\n                    <div class=\"section-subtitle\">Search, edit, assign students, or remove vehicles.</div>\r\n                </div>\r\n            </div>\r\n        </div>\r\n        <div class=\"filters\">\r\n            <input id=\"searchInput\" placeholder=\"Search by vehicle no, route, driver, phone\">\r\n            <select id=\"statusFilter\">\r\n                <option value=\"all\">All Status</option>\r\n                <option value=\"active\">Active</option>\r\n                <option value=\"maintenance\">Maintenance</option>\r\n                <option value=\"inactive\">Inactive</option>\r\n            </select>\r\n            <select id=\"typeFilter\">\r\n                <option value=\"all\">All Types</option>\r\n                <option value=\"Bus\">Bus</option>\r\n                <option value=\"Van\">Van</option>\r\n                <option value=\"Mini Bus\">Mini Bus</option>\r\n                <option value=\"Other\">Other</option>\r\n            </select>\r\n        </div>\r\n        <div class=\"list\" id=\"vehicleList\"></div>\r\n    </div>\r\n</div>\r\n\r\n<!-- Assign students modal -->\r\n<div class=\"modal-overlay\" id=\"assignModal\">\r\n    <div class=\"modal-box\" onclick=\"event.stopPropagation()\">\r\n        <div class=\"modal-header\">\r\n            <h3 id=\"assignModalTitle\">Assign Students</h3>\r\n            <p id=\"assignModalSub\">Loading vehicle info...</p>\r\n        </div>\r\n        <div class=\"modal-body\">\r\n            <!-- Assigned students list -->\r\n            <div class=\"assigned-list-section\">\r\n                <h4>Currently Assigned Students (<span id=\"assignedCount\">0</span>)</h4>\r\n                <div id=\"assignedStudentsList\">\r\n                    <div class=\"loading-msg\">Loading...</div>\r\n                </div>\r\n            </div>\r\n\r\n            <div class=\"section-divider\"></div>\r\n\r\n            <!-- Search to add students -->\r\n            <div class=\"field-group\" style=\"margin-bottom:12px;\">\r\n                <label class=\"field-label\">Search & Add Student</label>\r\n                <span class=\"field-hint\">Student ka naam ya ID daalo. Sirf usi school ke students dikhenge.</span>\r\n            </div>\r\n            <div class=\"search-box\">\r\n                <input id=\"studentSearchInput\" placeholder=\"Name ya Student ID...\" autocomplete=\"off\">\r\n                <button type=\"button\" class=\"btn-primary\" onclick=\"searchStudents()\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"M21 21l-4.3-4.3\"/></svg>Search</button>\r\n            </div>\r\n            <div id=\"studentSearchResults\">\r\n                <div class=\"empty\" style=\"font-size:13px;\">Student dhundho upar se - naam ya ID daalo.</div>\r\n            </div>\r\n        </div>\r\n        <div class=\"modal-footer\">\r\n            <button type=\"button\" class=\"btn-secondary\" onclick=\"closeAssignModal()\"><svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M18 6L6 18\"/><path d=\"M6 6l12 12\"/></svg>Close</button>\r\n        </div>\r\n    </div>\r\n</div>\r\n\r\n<script src=\"school-branding.js\"></script>\r\n<script type=\"module\">\r\nimport { initializeApp } from \"./firebase-compat.js\";\r\nimport { getAuth, onAuthStateChanged, signOut, createUserWithEmailAndPassword } from \"./firebase-compat.js\";\r\nimport {\r\n    getFirestore, doc, getDoc, collection, getDocs,\r\n    addDoc, updateDoc, deleteDoc, setDoc, serverTimestamp,\r\n    query, where, arrayUnion, arrayRemove\r\n} from \"./firebase-compat.js\";\r\nimport { calibratedSpeedKmh, createVehicleMap, locationStatus } from \"./schoolix-maplibre.js\";\r\nimport { activeTrips, assignDriver, deactivateStudentTransport, isTransportAccessDenied, isTransportDriverReferenceMissing, isTransportSetupMissing, liveLocations, startTrip, stopTrip, subscribeTransport, upsertDriver, upsertStudentTransport, upsertVehicle } from \"./schoolix-transport.js\";\r\n\r\nconst firebaseConfig = {\r\n    apiKey: \"@secret:GOOGLE_API_KEY\",\r\n    authDomain: \"schoolix-48107.firebaseapp.com\",\r\n    projectId: \"schoolix-48107\",\r\n    storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n    messagingSenderId: \"133937954491\",\r\n    appId: \"1:133937954491:web:69d8064422617eb8c4339e\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\r\nconst db = getFirestore(app);\r\n\r\nconst vehicleForm   = document.getElementById(\"vehicleForm\");\r\nconst routeForm     = document.getElementById(\"routeForm\");\r\nconst vehicleListEl = document.getElementById(\"vehicleList\");\r\nconst routeListEl   = document.getElementById(\"routeList\");\r\nconst searchInput   = document.getElementById(\"searchInput\");\r\nconst statusFilter  = document.getElementById(\"statusFilter\");\r\nconst typeFilter    = document.getElementById(\"typeFilter\");\r\nconst formTitleEl   = document.getElementById(\"formTitle\");\r\nconst saveBtnEl     = document.getElementById(\"saveBtn\");\r\nconst vehicleRouteSelect = document.getElementById(\"vehicleRouteSelect\");\r\nconst routeLookupInput   = document.getElementById(\"routeLookupInput\");\r\nconst routeLookupResult  = document.getElementById(\"routeLookupResult\");\r\n\r\nlet adminId = null;\r\nlet vehicles = [];\r\nlet routes = [];\r\nlet allStudents = [];\r\nlet filteredVehicles = [];\r\nlet editingVehicleId = null;\r\nlet assigningVehicleId = null;\r\nlet adminMap = null;\r\nlet liveLocationRows = [];\r\nlet activeTripRows = [];\r\nlet vehicleListLoading = true;\r\nlet routeListLoading = true;\r\nlet liveMapRefreshTimer = 0;\r\n\r\nwindow.SchoolixTransportLiveRefreshMs = 3000;\r\n\r\nconst ICONS = {\r\n    search: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"M21 21l-4.3-4.3\"/></svg>',\r\n    users: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>',\r\n    edit: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z\"/></svg>',\r\n    trash: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 6h18\"/><path d=\"M8 6V4h8v2\"/><path d=\"M19 6l-1 14H6L5 6\"/></svg>',\r\n    route: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"6\" cy=\"19\" r=\"3\"/><path d=\"M9 19h8.5a3.5 3.5 0 0 0 0-7H8a3 3 0 0 1 0-6h10\"/><circle cx=\"18\" cy=\"5\" r=\"3\"/></svg>',\r\n    bus: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M8 6v6\"/><path d=\"M15 6v6\"/><path d=\"M2 12h19.6\"/><path d=\"M18 18h3s.5-1.7.8-3.2c.1-.7.2-1.4.2-2.1V8a3 3 0 0 0-3-3H5a3 3 0 0 0-3 3v10h3\"/><circle cx=\"7\" cy=\"18\" r=\"2\"/><circle cx=\"16\" cy=\"18\" r=\"2\"/></svg>',\r\n    play: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polygon points=\"6 3 20 12 6 21 6 3\"/></svg>',\r\n    stop: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"6\" y=\"6\" width=\"12\" height=\"12\" rx=\"2\"/></svg>'\r\n};\r\n\r\nfunction escHtml(s) {\r\n    if (s == null || s === \"\") return \"\";\r\n    return String(s).replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\").replace(/\"/g,\"&quot;\");\r\n}\r\n\r\nfunction skeletonCards(count = 3) {\r\n    return Array.from({ length: count }, () => `\r\n        <div class=\"sx-skeleton-card\" aria-hidden=\"true\">\r\n            <div class=\"sx-skeleton-line w60\"></div>\r\n            <div class=\"sx-skeleton-line w80\"></div>\r\n            <div class=\"sx-skeleton-line\"></div>\r\n        </div>\r\n    `).join(\"\");\r\n}\r\n\r\nfunction setPageBusy(visible, title = \"Loading transport workspace...\", text = \"Fetching routes, vehicles and live tracking status.\") {\r\n    const overlay = document.getElementById(\"transportPageBusy\");\r\n    if (!overlay) return;\r\n    document.getElementById(\"transportBusyTitle\").textContent = title;\r\n    document.getElementById(\"transportBusyText\").textContent = text;\r\n    overlay.classList.toggle(\"is-visible\", Boolean(visible));\r\n    overlay.setAttribute(\"aria-hidden\", String(!visible));\r\n}\r\n\r\nfunction setButtonBusy(button, busy, label = \"Working...\") {\r\n    if (!button) return;\r\n    if (busy) {\r\n        button.dataset.originalHtml = button.dataset.originalHtml || button.innerHTML;\r\n        button.disabled = true;\r\n        button.innerHTML = `<span class=\"sx-spinner\" style=\"width:16px;height:16px;margin:0;border-width:2px;\"></span>${escHtml(label)}`;\r\n    } else {\r\n        button.disabled = false;\r\n        if (button.dataset.originalHtml) {\r\n            button.innerHTML = button.dataset.originalHtml;\r\n            delete button.dataset.originalHtml;\r\n        }\r\n        if (button.id === \"saveBtn\" && !editingVehicleId) {\r\n            button.innerHTML = saveVehicleButtonHtml(\"Save Vehicle\");\r\n        }\r\n    }\r\n}\r\n\r\nfunction saveVehicleButtonHtml(label = \"Save Vehicle\") {\r\n    return `<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z\"/><path d=\"M17 21v-8H7v8\"/><path d=\"M7 3v5h8\"/></svg>${escHtml(label)}`;\r\n}\r\n\r\nfunction currentActionButton() {\r\n    const active = document.activeElement;\r\n    return active?.tagName === \"BUTTON\" ? active : null;\r\n}\r\n\r\nfunction clearMapMissing(mapApi, vehicleIds = []) {\r\n    if (typeof mapApi?.clearMissing === \"function\") {\r\n        mapApi.clearMissing(vehicleIds);\r\n        return;\r\n    }\r\n    const keep = new Set(vehicleIds.map((id) => String(id)));\r\n    mapApi?.markers?.forEach?.((entry, id) => {\r\n        if (!keep.has(String(id))) {\r\n            entry?.marker?.remove?.();\r\n            mapApi.markers.delete(id);\r\n        }\r\n    });\r\n}\r\n\r\nvehicleListEl.innerHTML = skeletonCards(4);\r\nrouteListEl.innerHTML = skeletonCards(2);\r\ndocument.getElementById(\"adminLiveVehicleList\").innerHTML = skeletonCards(3);\r\n\r\nonAuthStateChanged(auth, async (user) => {\r\n    setPageBusy(true);\r\n    if (!user) { window.location.href = \"#/index.html\"; return; }\r\n    try {\r\n        const userDoc = await getDoc(doc(db, \"users\", user.uid));\r\n        if (!userDoc.exists() || userDoc.data().role !== \"admin\") {\r\n            alert(\"Access denied.\");\r\n            window.location.href = \"#/index.html\";\r\n            return;\r\n        }\r\n        adminId = user.uid;\r\n        await loadRoutes();\r\n        await loadVehicles();\r\n        adminMap = await createVehicleMap(document.getElementById(\"adminLiveMap\"), { zoom: 12, recenterLabel: \"Show active vehicles\" });\r\n        await loadAllStudents();\r\n        await refreshActiveTrips();\r\n        await refreshAdminLiveMap();\r\n        subscribeTransport(\"schoolix_vehicle_live_locations\", `school_id=eq.${adminId}`, refreshAdminLiveMap, refreshAdminLiveMap);\r\n        subscribeTransport(\"schoolix_transport_trips\", `school_id=eq.${adminId}`, refreshActiveTrips, refreshActiveTrips);\r\n    } finally {\r\n        setPageBusy(false);\r\n    }\r\n});\r\n\r\n/* Students cache */\r\nasync function loadAllStudents() {\r\n    try {\r\n        const snap = await getDocs(collection(db, \"schools\", adminId, \"students\"));\r\n        allStudents = snap.docs.map(d => ({ id: d.id, ...d.data() }));\r\n    } catch(e) { console.error(\"Load students failed:\", e); }\r\n}\r\n\r\n/* Assign modal */\r\nwindow.openAssignModal = async (vehicleId) => {\r\n    assigningVehicleId = vehicleId;\r\n    const v = vehicles.find(x => x.id === vehicleId);\r\n    if (!v) return;\r\n\r\n    document.getElementById(\"assignModalTitle\").textContent =\r\n        `Assign Students - ${v.vehicleNumber}`;\r\n    document.getElementById(\"assignModalSub\").textContent =\r\n        `${v.vehicleType} - Driver: ${v.driverName} - Capacity: ${v.capacity} seats`;\r\n    document.getElementById(\"studentSearchInput\").value = \"\";\r\n    document.getElementById(\"studentSearchResults\").innerHTML =\r\n        `<div class=\"empty\" style=\"font-size:13px;\">Student dhundho upar se - naam ya ID daalo.</div>`;\r\n\r\n    document.getElementById(\"assignModal\").classList.add(\"open\");\r\n    await renderAssignedStudents(v);\r\n};\r\n\r\nwindow.closeAssignModal = () => {\r\n    document.getElementById(\"assignModal\").classList.remove(\"open\");\r\n    assigningVehicleId = null;\r\n};\r\n\r\ndocument.getElementById(\"assignModal\").addEventListener(\"click\", function(e) {\r\n    if (e.target === this) closeAssignModal();\r\n});\r\n\r\nasync function renderAssignedStudents(v) {\r\n    const list  = document.getElementById(\"assignedStudentsList\");\r\n    const count = document.getElementById(\"assignedCount\");\r\n    const assigned = Array.isArray(v.assignedStudentIds) ? v.assignedStudentIds : [];\r\n    count.textContent = assigned.length;\r\n\r\n    if (!assigned.length) {\r\n        list.innerHTML = `<div class=\"empty\" style=\"font-size:13px;\">Abhi koi student assign nahi hai.</div>`;\r\n        return;\r\n    }\r\n\r\n    list.innerHTML = `<div class=\"loading-msg\">Loading assigned students...</div>`;\r\n\r\n    // Get student details for assigned IDs\r\n    const items = assigned.map(sid => {\r\n        const s = allStudents.find(st => st.studentId === sid || st.id === sid);\r\n        return s || { studentId: sid, name: \"Unknown Student\", class: \"-\", section: \"\" };\r\n    });\r\n\r\n    // Get student tracking data\r\n    const studentTracking = v.studentTracking || {};\r\n\r\n    list.innerHTML = items.map(s => {\r\n        const sid = s.studentId || s.id;\r\n        const tracking = studentTracking[sid] || {};\r\n        \r\n        return `\r\n        <div class=\"assigned-item\" style=\"flex-direction:column;align-items:flex-start;gap:12px;padding:14px;\">\r\n            <div class=\"ai-info\" style=\"width:100%;\">\r\n                <strong>${escHtml(s.name)}</strong>\r\n                <span>ID: ${escHtml(sid)} - Class: ${escHtml(s.class||\"-\")}${s.section ? \"-\"+escHtml(s.section) : \"\"}</span>\r\n            </div>\r\n            <div style=\"width:100%;display:grid;grid-template-columns:1fr 1fr;gap:8px;\">\r\n                <div style=\"background:#ede9fe;border:1px solid #c4b5fd;border-radius:8px;padding:10px;\">\r\n                    <div style=\"font-size:11px;font-weight:700;color:#5b21b6;text-transform:uppercase;margin-bottom:6px;\">Pickup Time</div>\r\n                    <input type=\"time\" style=\"width:100%;padding:6px;border:1px solid #c4b5fd;border-radius:6px;font-size:12px;\" \r\n                        id=\"pickup_${escHtml(sid)}\" value=\"${tracking.pickupTime || ''}\" \r\n                        onchange=\"updateStudentTracking('${escHtml(sid)}', 'pickupTime', this.value)\">\r\n                    <div style=\"font-size:11px;font-weight:700;color:#5b21b6;text-transform:uppercase;margin:12px 0 6px;\">Pickup Place</div>\r\n                    <input type=\"text\" placeholder=\"Enter pickup place\" style=\"width:100%;padding:8px;border:1px solid #c4b5fd;border-radius:6px;font-size:12px;\" \r\n                        id=\"pickupPlace_${escHtml(sid)}\" value=\"${escHtml(tracking.pickupPlace || '')}\" \r\n                        onchange=\"updateStudentTracking('${escHtml(sid)}', 'pickupPlace', this.value)\">\r\n                </div>\r\n                <div style=\"background:#dcfce7;border:1px solid #86efac;border-radius:8px;padding:10px;\">\r\n                    <div style=\"font-size:11px;font-weight:700;color:#166534;text-transform:uppercase;margin-bottom:6px;\">Drop-off Time</div>\r\n                    <input type=\"time\" style=\"width:100%;padding:6px;border:1px solid #86efac;border-radius:6px;font-size:12px;\" \r\n                        id=\"dropoff_${escHtml(sid)}\" value=\"${tracking.dropoffTime || ''}\" \r\n                        onchange=\"updateStudentTracking('${escHtml(sid)}', 'dropoffTime', this.value)\">\r\n                    <div style=\"font-size:11px;font-weight:700;color:#166534;text-transform:uppercase;margin:12px 0 6px;\">Drop-off Place</div>\r\n                    <input type=\"text\" placeholder=\"Enter drop-off place\" style=\"width:100%;padding:8px;border:1px solid #86efac;border-radius:6px;font-size:12px;\" \r\n                        id=\"dropoffPlace_${escHtml(sid)}\" value=\"${escHtml(tracking.dropoffPlace || '')}\" \r\n                        onchange=\"updateStudentTracking('${escHtml(sid)}', 'dropoffPlace', this.value)\">\r\n                </div>\r\n            </div>\r\n            <button type=\"button\" class=\"btn-danger\" style=\"padding:6px 12px;font-size:12px;width:100%;\"\r\n                onclick=\"removeStudentFromVehicle('${escHtml(sid)}')\">Remove Student</button>\r\n        </div>\r\n    `;\r\n    }).join(\"\");\r\n}\r\n\r\nwindow.searchStudents = async () => {\r\n    const q = document.getElementById(\"studentSearchInput\").value.trim().toLowerCase();\r\n    const resultsEl = document.getElementById(\"studentSearchResults\");\r\n\r\n    if (!q) {\r\n        resultsEl.innerHTML = `<div class=\"empty\" style=\"font-size:13px;\">Kuch type karo phir search karo.</div>`;\r\n        return;\r\n    }\r\n\r\n    const v = vehicles.find(x => x.id === assigningVehicleId);\r\n    const alreadyAssigned = v ? (Array.isArray(v.assignedStudentIds) ? v.assignedStudentIds : []) : [];\r\n\r\n    const matches = allStudents.filter(s =>\r\n        (s.name || \"\").toLowerCase().includes(q) ||\r\n        (s.studentId || \"\").toLowerCase().includes(q) ||\r\n        (s.id || \"\").toLowerCase().includes(q)\r\n    );\r\n\r\n    if (!matches.length) {\r\n        resultsEl.innerHTML = `<div class=\"empty\" style=\"font-size:13px;\">Koi student nahi mila \"${escHtml(q)}\" ke liye.</div>`;\r\n        return;\r\n    }\r\n\r\n    resultsEl.innerHTML = `<div class=\"student-search-result\">${matches.slice(0, 10).map(s => {\r\n        const sid = s.studentId || s.id;\r\n        const isAssigned = alreadyAssigned.includes(sid);\r\n        return `<div class=\"sr-item\">\r\n            <div class=\"sr-info\">\r\n                <strong>${escHtml(s.name)}</strong>\r\n                <span>ID: ${escHtml(sid)} - Class: ${escHtml(s.class||\"-\")}${s.section?\"-\"+escHtml(s.section):\"\"} - ${escHtml(s.phone||\"\")}</span>\r\n            </div>\r\n            ${isAssigned\r\n                ? `<span class=\"pill active\" style=\"margin-left:0;white-space:nowrap;display:inline-flex;align-items:center;gap:5px;\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M20 6L9 17l-5-5\"/></svg>Assigned</span>`\r\n                : `<button type=\"button\" class=\"btn-teal\" style=\"padding:6px 12px;font-size:12px;white-space:nowrap;\"\r\n                    onclick=\"assignStudentToVehicle('${escHtml(sid)}', '${escHtml(s.name)}')\">Assign</button>`\r\n            }\r\n        </div>`;\r\n    }).join(\"\")}</div>`;\r\n};\r\n\r\nwindow.assignStudentToVehicle = async (studentId, studentName) => {\r\n    if (!assigningVehicleId || !studentId) return;\r\n    try {\r\n        const v = vehicles.find(x => x.id === assigningVehicleId);\r\n        if (!v) return;\r\n        const vRef = doc(db, \"schools\", adminId, \"vehicles\", assigningVehicleId);\r\n        await updateDoc(vRef, {\r\n            assignedStudentIds: arrayUnion(studentId),\r\n            updatedAt: serverTimestamp()\r\n        });\r\n        const transportSynced = await upsertStudentTransport({\r\n            school_id: adminId,\r\n            student_id: studentId,\r\n            vehicle_id: assigningVehicleId,\r\n            route_id: v.routeId || null,\r\n            active: true,\r\n            updated_at: new Date().toISOString()\r\n        }).then(() => true).catch(error => {\r\n            console.warn(\"Student transport sync failed\", error);\r\n            return false;\r\n        });\r\n\r\n        // Also update student doc with vehicleId for easy reverse lookup\r\n        const sQuery = query(collection(db, \"schools\", adminId, \"students\"),\r\n            where(\"studentId\", \"==\", studentId));\r\n        const sSnap = await getDocs(sQuery);\r\n        if (!sSnap.empty) {\r\n            await updateDoc(doc(db, \"schools\", adminId, \"students\", sSnap.docs[0].id), {\r\n                assignedVehicleId: assigningVehicleId\r\n            });\r\n        }\r\n\r\n        showToast(\r\n            transportSynced ? `${studentName} assigned successfully!` : `${studentName} assigned. Live tracking sync pending.`,\r\n            transportSynced ? \"success\" : \"info\"\r\n        );\r\n        await loadVehicles();\r\n        await loadAllStudents();\r\n        const updatedV = vehicles.find(x => x.id === assigningVehicleId);\r\n        if (updatedV) {\r\n            await renderAssignedStudents(updatedV);\r\n            document.getElementById(\"assignedCount\").textContent =\r\n                (updatedV.assignedStudentIds || []).length;\r\n        }\r\n        // Refresh search results\r\n        await searchStudents();\r\n    } catch(e) {\r\n        console.error(e);\r\n        showToast(\"Assignment failed!\", \"error\");\r\n    }\r\n};\r\n\r\nwindow.updateStudentTracking = async (studentId, field, value) => {\r\n    if (!assigningVehicleId || !studentId) return;\r\n    try {\r\n        const v = vehicles.find(x => x.id === assigningVehicleId);\r\n        if (!v) return;\r\n        \r\n        const tracking = v.studentTracking || {};\r\n        if (!tracking[studentId]) tracking[studentId] = {};\r\n        tracking[studentId][field] = value;\r\n        \r\n        const vRef = doc(db, \"schools\", adminId, \"vehicles\", assigningVehicleId);\r\n        await updateDoc(vRef, {\r\n            studentTracking: tracking,\r\n            updatedAt: serverTimestamp()\r\n        });\r\n        \r\n        const fieldLabels = {\r\n            pickupTime: 'Pickup time',\r\n            dropoffTime: 'Drop-off time',\r\n            pickupPlace: 'Pickup place',\r\n            dropoffPlace: 'Drop-off place'\r\n        };\r\n        showToast(`${fieldLabels[field] || 'Update'} saved!`, \"success\");\r\n        await loadVehicles();\r\n    } catch(e) {\r\n        console.error(e);\r\n        showToast(\"Update failed!\", \"error\");\r\n    }\r\n};\r\n\r\nwindow.removeStudentFromVehicle = async (studentId) => {\r\n    if (!assigningVehicleId || !studentId) return;\r\n    if (!confirm(`Remove student ${studentId} from this vehicle?`)) return;\r\n    try {\r\n        const v = vehicles.find(x => x.id === assigningVehicleId);\r\n        if (!v) return;\r\n        \r\n        const tracking = v.studentTracking || {};\r\n        delete tracking[studentId];\r\n        \r\n        const vRef = doc(db, \"schools\", adminId, \"vehicles\", assigningVehicleId);\r\n        await updateDoc(vRef, {\r\n            assignedStudentIds: arrayRemove(studentId),\r\n            studentTracking: tracking,\r\n            updatedAt: serverTimestamp()\r\n        });\r\n        await deactivateStudentTransport(adminId, studentId, assigningVehicleId)\r\n            .catch(error => console.warn(\"Student transport deactivate failed\", error));\r\n\r\n        // Remove from student doc too\r\n        const sQuery = query(collection(db, \"schools\", adminId, \"students\"),\r\n            where(\"studentId\", \"==\", studentId));\r\n        const sSnap = await getDocs(sQuery);\r\n        if (!sSnap.empty) {\r\n            await updateDoc(doc(db, \"schools\", adminId, \"students\", sSnap.docs[0].id), {\r\n                assignedVehicleId: \"\"\r\n            });\r\n        }\r\n\r\n        showToast(\"Student removed.\", \"info\");\r\n        await loadVehicles();\r\n        await loadAllStudents();\r\n        const updatedV = vehicles.find(x => x.id === assigningVehicleId);\r\n        if (updatedV) await renderAssignedStudents(updatedV);\r\n    } catch(e) {\r\n        console.error(e);\r\n        showToast(\"Remove failed!\", \"error\");\r\n    }\r\n};\r\n\r\n/* Toast */\r\nfunction showToast(msg, type=\"info\") {\r\n    const t = document.createElement(\"div\");\r\n    t.className = `sx-toast ${type}`;\r\n    t.setAttribute(\"role\", \"status\");\r\n    t.textContent = msg;\r\n    document.body.appendChild(t);\r\n    requestAnimationFrame(() => t.classList.add(\"is-visible\"));\r\n    setTimeout(() => {\r\n        t.classList.remove(\"is-visible\");\r\n        setTimeout(()=>t.remove(), 220);\r\n    }, 3200);\r\n}\r\n\r\n/* Routes */\r\nasync function generateRouteId() {\r\n    const snap = await getDocs(collection(db, \"schools\", adminId, \"routes\"));\r\n    const existing = new Set();\r\n    snap.forEach(d => { if (d.data().routeId) existing.add(String(d.data().routeId)); });\r\n    let id = \"\";\r\n    do { id = `RT${Math.floor(100000 + Math.random() * 900000)}`; } while (existing.has(id));\r\n    return id;\r\n}\r\n\r\nfunction getViaStopsFromForm() {\r\n    return [...document.getElementById(\"viaStopsContainer\").querySelectorAll(\".via-stop-input\")]\r\n        .map(el => el.value.trim()).filter(Boolean);\r\n}\r\n\r\nwindow.addViaStopRow = (preset = \"\") => {\r\n    const container = document.getElementById(\"viaStopsContainer\");\r\n    const row = document.createElement(\"div\");\r\n    row.className = \"via-row\";\r\n    const inp = document.createElement(\"input\");\r\n    inp.type = \"text\"; inp.className = \"via-stop-input\";\r\n    inp.placeholder = \"Via stop - area / landmark\";\r\n    if (preset) inp.value = preset;\r\n    const btn = document.createElement(\"button\");\r\n    btn.type = \"button\"; btn.className = \"btn-danger\"; btn.innerHTML = `${ICONS.trash}Remove`;\r\n    btn.addEventListener(\"click\", () => row.remove());\r\n    row.appendChild(inp); row.appendChild(btn);\r\n    container.appendChild(row); inp.focus();\r\n};\r\n\r\nfunction clearViaStopsForm() { document.getElementById(\"viaStopsContainer\").innerHTML = \"\"; }\r\n\r\nrouteForm.addEventListener(\"submit\", async (e) => {\r\n    e.preventDefault();\r\n    const submitBtn = routeForm.querySelector('button[type=\"submit\"]');\r\n    const from = document.getElementById(\"routeFrom\").value.trim();\r\n    const to   = document.getElementById(\"routeTo\").value.trim();\r\n    const notes= document.getElementById(\"routeNotes\").value.trim();\r\n    const via  = getViaStopsFromForm();\r\n    if (!from || !to) { alert(\"From and To are required.\"); return; }\r\n    try {\r\n        setButtonBusy(submitBtn, true, \"Saving route...\");\r\n        const routeId = await generateRouteId();\r\n        await addDoc(collection(db, \"schools\", adminId, \"routes\"), {\r\n            routeId, from, to, via, notes: notes||\"\",\r\n            createdAt: serverTimestamp(), updatedAt: serverTimestamp()\r\n        });\r\n        showToast(`Route saved: ${routeId}`, \"success\");\r\n        routeForm.reset(); clearViaStopsForm();\r\n        await loadRoutes();\r\n    } catch(e) { console.error(e); alert(\"Failed to save route.\"); }\r\n    finally { setButtonBusy(submitBtn, false); }\r\n});\r\n\r\nasync function loadRoutes() {\r\n    try {\r\n        if (routeListLoading) routeListEl.innerHTML = skeletonCards(2);\r\n        const snap = await getDocs(collection(db, \"schools\", adminId, \"routes\"));\r\n        routes = snap.docs.map(d => ({ id: d.id, ...d.data() }));\r\n        routeListLoading = false;\r\n        document.getElementById(\"totalRoutes\").textContent = routes.length;\r\n        const heroRoutes = document.getElementById(\"heroSavedRoutes\");\r\n        if (heroRoutes) heroRoutes.textContent = String(routes.length);\r\n        populateRouteDropdown();\r\n        renderRouteList();\r\n    } catch(e) { routeListLoading = false; routeListEl.innerHTML = '<div class=\"empty\">Failed to load routes.</div>'; }\r\n}\r\n\r\nfunction populateRouteDropdown() {\r\n    const current = vehicleRouteSelect.value;\r\n    vehicleRouteSelect.innerHTML = '<option value=\"\">- No saved route - use manual name below</option>';\r\n    routes.forEach(r => {\r\n        const via = Array.isArray(r.via) ? r.via : [];\r\n        const opt = document.createElement(\"option\");\r\n        opt.value = r.routeId;\r\n        opt.textContent = `${r.routeId}: ${r.from} - ${r.to}${via.length?\" (\"+via.length+\" via)\":\"\"}`;\r\n        opt.dataset.docId = r.id;\r\n        vehicleRouteSelect.appendChild(opt);\r\n    });\r\n    if ([...vehicleRouteSelect.options].some(o => o.value === current)) vehicleRouteSelect.value = current;\r\n}\r\n\r\nfunction renderRouteList() {\r\n    routeListEl.innerHTML = \"\";\r\n    if (!routes.length) { routeListEl.innerHTML = '<div class=\"empty\">No routes saved yet.</div>'; return; }\r\n    routes.forEach(r => {\r\n        const row = document.createElement(\"div\");\r\n        row.className = \"route-card\";\r\n        const via = Array.isArray(r.via) ? r.via : [];\r\n        const viaBlock = via.length\r\n            ? `<br><strong>Via:</strong><ol class=\"via-stops-list\">${via.map(s=>`<li>${escHtml(s)}</li>`).join(\"\")}</ol>`\r\n            : \"\";\r\n        row.innerHTML = `\r\n            <div class=\"meta\">\r\n                <strong class=\"route-id-badge\">${escHtml(r.routeId)}</strong>\r\n                <span class=\"pill active\" style=\"margin-left:8px;\">${ICONS.route}${escHtml(r.from)} - ${escHtml(r.to)}</span>\r\n                ${viaBlock}\r\n                ${r.notes ? `<br>Notes: ${escHtml(r.notes)}` : \"\"}\r\n            </div>\r\n            <div class=\"action-col\">\r\n                <button type=\"button\" class=\"btn-success\" onclick=\"useRouteLookup('${escHtml(r.routeId)}')\">${ICONS.search}Show details</button>\r\n                <button type=\"button\" class=\"btn-danger\" onclick=\"deleteRoute('${escHtml(r.id)}')\">${ICONS.trash}Delete</button>\r\n            </div>`;\r\n        routeListEl.appendChild(row);\r\n    });\r\n}\r\n\r\nwindow.fetchRouteById = async () => {\r\n    const raw = routeLookupInput.value.trim().toUpperCase();\r\n    if (!raw) { alert(\"Enter a Route ID.\"); return; }\r\n    const trigger = document.activeElement?.tagName === \"BUTTON\" ? document.activeElement : null;\r\n    try {\r\n        setButtonBusy(trigger, true, \"Fetching...\");\r\n        const q = query(collection(db, \"schools\", adminId, \"routes\"), where(\"routeId\", \"==\", raw));\r\n        const snap = await getDocs(q);\r\n        if (snap.empty) { routeLookupResult.classList.remove(\"show\"); alert(\"No route found.\"); return; }\r\n        const data = snap.docs[0].data();\r\n        document.getElementById(\"lookupRouteId\").textContent = data.routeId || raw;\r\n        document.getElementById(\"lookupFrom\").textContent   = data.from || \"-\";\r\n        document.getElementById(\"lookupTo\").textContent     = data.to || \"-\";\r\n        document.getElementById(\"lookupNotes\").textContent  = data.notes || \"-\";\r\n        const via = Array.isArray(data.via) ? data.via : [];\r\n        const viaBlock = document.getElementById(\"lookupViaBlock\");\r\n        const viaList  = document.getElementById(\"lookupViaList\");\r\n        viaList.innerHTML = \"\";\r\n        if (via.length) {\r\n            via.forEach(s => { const li = document.createElement(\"li\"); li.textContent = s; viaList.appendChild(li); });\r\n            viaBlock.style.display = \"block\";\r\n        } else { viaBlock.style.display = \"none\"; }\r\n        routeLookupResult.classList.add(\"show\");\r\n    } catch(e) { alert(\"Could not fetch route.\"); }\r\n    finally { setButtonBusy(trigger, false); }\r\n};\r\n\r\nwindow.useRouteLookup = (routeId) => {\r\n    routeLookupInput.value = routeId; fetchRouteById();\r\n    document.getElementById(\"routeLookupCard\")?.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\r\n};\r\n\r\nwindow.resetRouteForm = () => { document.getElementById(\"routeForm\").reset(); clearViaStopsForm(); };\r\n\r\nwindow.deleteRoute = async (docId) => {\r\n    if (!confirm(\"Delete this route?\")) return;\r\n    try {\r\n        setPageBusy(true, \"Deleting route...\", \"Updating route list and vehicle route dropdown.\");\r\n        await deleteDoc(doc(db, \"schools\", adminId, \"routes\", docId));\r\n        await loadRoutes(); await loadVehicles();\r\n        showToast(\"Route deleted.\", \"info\");\r\n    } catch(e) { alert(\"Failed to delete.\"); }\r\n    finally { setPageBusy(false); }\r\n};\r\n\r\n/* Vehicles */\r\nfunction isUuid(value = \"\") {\r\n    return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value || \"\").trim());\r\n}\r\n\r\nfunction trackingVehiclePayload(vehicleId, v = {}) {\r\n    return {\r\n        id: vehicleId,\r\n        school_id: adminId,\r\n        vehicle_number: v.vehicleNumber || vehicleId,\r\n        vehicle_type: v.vehicleType || \"Bus\",\r\n        route_id: v.routeId || null,\r\n        driver_id: v.driverId || null,\r\n        status: v.status || \"active\",\r\n        data: {\r\n            driverName: v.driverName || \"\",\r\n            driverPhone: v.driverPhone || \"\",\r\n            driverEmail: v.driverEmail || \"\",\r\n            routeName: v.routeName || \"\",\r\n            capacity: v.capacity || 0\r\n        },\r\n        updated_at: new Date().toISOString()\r\n    };\r\n}\r\n\r\nasync function findUserByEmail(email) {\r\n    const cleanEmail = String(email || \"\").trim().toLowerCase();\r\n    if (!cleanEmail) return null;\r\n    const snap = await getDocs(query(collection(db, \"users\"), where(\"email\", \"==\", cleanEmail)));\r\n    if (!snap.empty) return { id: snap.docs[0].id, ...snap.docs[0].data() };\r\n    const authSnap = await getDocs(query(collection(db, \"users\"), where(\"authEmail\", \"==\", cleanEmail)));\r\n    if (!authSnap.empty) return { id: authSnap.docs[0].id, ...authSnap.docs[0].data() };\r\n    return null;\r\n}\r\n\r\nasync function ensureDriverLogin(vehicleId, payload) {\r\n    const email = String(payload.driverEmail || \"\").trim().toLowerCase();\r\n    const password = document.getElementById(\"driverPassword\").value.trim();\r\n    if (!email) return {};\r\n\r\n    let userProfile = await findUserByEmail(email);\r\n    let authUid = String(userProfile?.authUid || userProfile?.uid || userProfile?.id || \"\").trim();\r\n\r\n    if (!userProfile) {\r\n        if (!password || password.length < 6) {\r\n            throw new Error(\"New driver login ke liye email ke saath minimum 6 character password set karo.\");\r\n        }\r\n        const cred = await createUserWithEmailAndPassword(auth, email, password);\r\n        authUid = cred.user.uid;\r\n        userProfile = { id: authUid };\r\n    }\r\n\r\n    const driverId = String(userProfile.driverId || userProfile.transportDriverId || authUid || email).trim();\r\n    const userDocId = String(userProfile.id || authUid).trim();\r\n    const profilePayload = {\r\n        name: payload.driverName || \"Driver\",\r\n        phone: payload.driverPhone,\r\n        email,\r\n        authEmail: email,\r\n        role: \"driver\",\r\n        schoolId: adminId,\r\n        adminId,\r\n        access: true,\r\n        status: \"active\",\r\n        assignedVehicleId: vehicleId,\r\n        driverId,\r\n        transportDriverId: driverId,\r\n        updatedAt: serverTimestamp()\r\n    };\r\n\r\n    if (authUid) {\r\n        profilePayload.authUid = authUid;\r\n        profilePayload.uid = authUid;\r\n    }\r\n\r\n    await setDoc(doc(db, \"users\", userDocId), profilePayload, { merge: true });\r\n\r\n    const driverRow = {\r\n        id: driverId,\r\n        school_id: adminId,\r\n        auth_uid: isUuid(authUid) ? authUid : null,\r\n        name: payload.driverName || \"Driver\",\r\n        phone: payload.driverPhone,\r\n        email,\r\n        assigned_vehicle_id: vehicleId,\r\n        status: \"active\",\r\n        data: {\r\n            vehicleNumber: payload.vehicleNumber,\r\n            userDocId,\r\n            authUid\r\n        },\r\n        updated_at: new Date().toISOString()\r\n    };\r\n    const driverSynced = await upsertDriver(driverRow)\r\n        .then(() => assignDriver(driverId, vehicleId, adminId))\r\n        .then(() => true)\r\n        .catch(error => {\r\n            console.warn(\"Driver transport sync skipped:\", error);\r\n            return false;\r\n        });\r\n    if (!driverSynced) showToast(\"Driver login created. Live tracking sync pending.\", \"info\");\r\n\r\n    return { driverId, driverAuthUid: authUid, driverEmail: email };\r\n}\r\n\r\nasync function safeUpsertTrackingVehicle(vehicleId, payload) {\r\n    try {\r\n        await upsertVehicle(trackingVehiclePayload(vehicleId, payload));\r\n        return true;\r\n    } catch (error) {\r\n        if (isTransportDriverReferenceMissing(error) && payload?.driverId) {\r\n            console.warn(\"Vehicle driver reference missing in transport sync; starting trip without linked driver row.\", error);\r\n            const withoutDriver = { ...payload, driverId: null };\r\n            await upsertVehicle(trackingVehiclePayload(vehicleId, withoutDriver));\r\n            return true;\r\n        }\r\n        throw error;\r\n    }\r\n}\r\n\r\nvehicleForm.addEventListener(\"submit\", async (e) => {\r\n    e.preventDefault();\r\n    const submitBtn = document.getElementById(\"saveBtn\");\r\n    const selectedRouteId = vehicleRouteSelect.value.trim();\r\n    const manualRouteName = document.getElementById(\"routeName\").value.trim();\r\n    let routeName = manualRouteName || \"Unassigned route\", routeFrom = \"\", routeTo = \"\", routeVia = [];\r\n    if (selectedRouteId) {\r\n        const r = routes.find(x => x.routeId === selectedRouteId);\r\n        if (r) { routeFrom=r.from||\"\"; routeTo=r.to||\"\"; routeVia=Array.isArray(r.via)?r.via:[]; if (!routeName) routeName=`${r.from} - ${r.to}`; }\r\n    }\r\n\r\n    const payload = {\r\n        vehicleNumber:   document.getElementById(\"vehicleNumber\").value.trim().toUpperCase(),\r\n        vehicleType:     document.getElementById(\"vehicleType\").value,\r\n        vehicleModel:    document.getElementById(\"vehicleModel\").value.trim(),\r\n        capacity:        Number(document.getElementById(\"capacity\").value||0),\r\n        driverName:      document.getElementById(\"driverName\").value.trim(),\r\n        driverPhone:     document.getElementById(\"driverPhone\").value.trim(),\r\n        driverEmail:     document.getElementById(\"driverEmail\").value.trim().toLowerCase(),\r\n        routeId: selectedRouteId||\"\", routeName, routeFrom, routeTo, routeVia,\r\n        permitExpiry:    document.getElementById(\"permitExpiry\").value||\"\",\r\n        insuranceExpiry: document.getElementById(\"insuranceExpiry\").value||\"\",\r\n        fitnessExpiry:   document.getElementById(\"fitnessExpiry\").value||\"\",\r\n        status:          document.getElementById(\"vehicleStatus\").value,\r\n        notes:           document.getElementById(\"notes\").value.trim(),\r\n        updatedAt:       serverTimestamp()\r\n    };\r\n\r\n    if (!payload.vehicleNumber || !payload.vehicleType) {\r\n        alert(\"Vehicle number and vehicle type are required.\"); return;\r\n    }\r\n    if (payload.driverEmail && !payload.driverName) {\r\n        alert(\"Driver login email ke saath driver name bhi daalo.\"); return;\r\n    }\r\n    const dup = vehicles.find(v => v.vehicleNumber===payload.vehicleNumber && v.id!==editingVehicleId);\r\n    if (dup) { alert(\"Vehicle number already exists.\"); return; }\r\n\r\n    try {\r\n        setButtonBusy(submitBtn, true, editingVehicleId ? \"Updating...\" : \"Saving...\");\r\n        let vehicleId = editingVehicleId;\r\n        if (editingVehicleId) {\r\n            await updateDoc(doc(db, \"schools\", adminId, \"vehicles\", editingVehicleId), payload);\r\n            showToast(\"Vehicle updated!\", \"success\");\r\n        } else {\r\n            const vehicleRef = await addDoc(collection(db, \"schools\", adminId, \"vehicles\"), {\r\n                ...payload, assignedStudentIds: [], createdAt: serverTimestamp()\r\n            });\r\n            vehicleId = vehicleRef.id;\r\n            showToast(\"Vehicle added!\", \"success\");\r\n        }\r\n        // A vehicle record belongs to Firestore. Live tracking is an optional\n        // Supabase integration, so an unavailable migration/RLS policy must not\n        // make a successfully saved vehicle look like it failed to save.\n        let trackingPending = false;\n        try {\n            await safeUpsertTrackingVehicle(vehicleId, payload);\n        } catch (error) {\n            trackingPending = true;\n            console.warn(\"Vehicle saved, but tracking sync is pending:\", error);\n        }\n\n        if (payload.driverEmail) {\n            try {\n                const driverMeta = await ensureDriverLogin(vehicleId, payload);\n                if (Object.keys(driverMeta).length) {\n                    await updateDoc(doc(db, \"schools\", adminId, \"vehicles\", vehicleId), {\n                        ...driverMeta,\n                        updatedAt: serverTimestamp()\n                    });\n                    try {\n                        await safeUpsertTrackingVehicle(vehicleId, { ...payload, ...driverMeta });\n                    } catch (error) {\n                        trackingPending = true;\n                        console.warn(\"Vehicle saved, but driver tracking sync is pending:\", error);\n                    }\n                    showToast(\"Driver login ready for phone app.\", \"success\");\n                }\n            } catch (error) {\n                // The vehicle is already saved. Keep the failure scoped to the\n                // optional driver-login setup instead of reporting a save error.\n                console.error(\"Driver login setup failed:\", error);\n                showToast(`Vehicle saved. Driver login setup pending: ${error.message || \"please try again.\"}`, \"info\");\n            }\n        }\n        if (trackingPending) {\n            showToast(\"Vehicle saved. Live tracking sync pending.\", \"info\");\n        }\n        resetForm(); await loadVehicles();\n    } catch(e) { console.error(e); alert(e.message || \"Failed to save vehicle.\"); }\r\n    finally { setButtonBusy(submitBtn, false); }\r\n});\r\n\r\nasync function loadVehicles() {\r\n    try {\r\n        if (vehicleListLoading) vehicleListEl.innerHTML = skeletonCards(4);\r\n        const snap = await getDocs(collection(db, \"schools\", adminId, \"vehicles\"));\r\n        vehicles = snap.docs.map(d => ({ id: d.id, ...d.data() }));\r\n        vehicleListLoading = false;\r\n        syncVehiclesForTracking();\r\n        filteredVehicles = [...vehicles];\r\n        updateStats(); renderVehicles();\r\n    } catch(e) { vehicleListLoading = false; vehicleListEl.innerHTML = '<div class=\"empty\">Failed to load records.</div>'; }\r\n}\r\n\r\nasync function syncVehiclesForTracking() {\r\n    Promise.all(vehicles.map(v => upsertVehicle(trackingVehiclePayload(v.id, v))\r\n        .catch(error => console.warn(\"Vehicle tracking sync failed\", v.id, error))));\r\n}\r\n\r\nfunction formatLiveAge(value) {\r\n    if (!value) return \"-\";\r\n    const seconds = Math.max(0, Math.round((Date.now() - new Date(value).getTime()) / 1000));\r\n    if (seconds < 60) return `${seconds}s ago`;\r\n    return `${Math.round(seconds / 60)}m ago`;\r\n}\r\n\r\nfunction queueLiveMapRefresh(repeats = 5, delay = 1800) {\r\n    window.clearTimeout(liveMapRefreshTimer);\r\n    const tick = async (left) => {\r\n        await refreshActiveTrips();\r\n        if (left > 1) liveMapRefreshTimer = window.setTimeout(() => tick(left - 1), delay);\r\n    };\r\n    liveMapRefreshTimer = window.setTimeout(() => tick(repeats), delay);\r\n}\r\n\r\nasync function refreshAdminLiveMap() {\r\n    const activeVehicleIds = activeTripRows.map(t => t.vehicle_id).filter(Boolean);\r\n    const vehicleIds = activeVehicleIds.length ? activeVehicleIds : vehicles.map(v => v.id);\r\n    const activeSet = new Set(activeVehicleIds);\r\n    liveLocationRows = await liveLocations(vehicleIds).catch(() => []);\r\n    if (activeSet.size) liveLocationRows = liveLocationRows.filter(loc => activeSet.has(loc.vehicle_id));\r\n    const byVehicle = new Map(vehicles.map(v => [v.id, v]));\r\n    const list = document.getElementById(\"adminLiveVehicleList\");\r\n    if (!list) return;\r\n    if (!liveLocationRows.length) {\r\n        if (activeSet.size) {\r\n            list.innerHTML = activeVehicleIds.map((vehicleId) => {\r\n                const v = byVehicle.get(vehicleId) || {};\r\n                return `<div class=\"live-vehicle-item is-waiting\">\r\n                    <strong>${escHtml(v.vehicleNumber || vehicleId)}</strong>\r\n                    <div>Driver: ${escHtml(v.driverName || \"-\")}</div>\r\n                    <div style=\"font-weight:800;color:#1d4ed8\">WAITING FOR FIRST GPS PING</div>\r\n                    <div>Driver app ko location permission ke saath logged in rakhein.</div>\r\n                </div>`;\r\n            }).join(\"\");\r\n        } else {\r\n            list.innerHTML = '<div class=\"empty\">No live GPS updates yet. Start tracking on a vehicle and keep the driver app logged in with location permission.</div>';\r\n        }\r\n        const heroLive = document.getElementById(\"heroLiveVehicles\");\r\n        if (heroLive) heroLive.textContent = \"0\";\r\n        clearMapMissing(adminMap, []);\r\n        return;\r\n    }\r\n    const heroLive = document.getElementById(\"heroLiveVehicles\");\r\n    if (heroLive) heroLive.textContent = String(liveLocationRows.length);\r\n    list.innerHTML = liveLocationRows.map(loc => {\r\n        const v = byVehicle.get(loc.vehicle_id) || {};\r\n        const status = locationStatus(loc.updated_at);\r\n        adminMap?.setVehicle(loc.vehicle_id, loc, v.vehicleNumber || v.vehicle_number || \"Vehicle\", {\r\n            driver: v.driverName || \"\",\r\n            route: v.routeName || \"\",\r\n            status\r\n        });\r\n        return `<div class=\"live-vehicle-item\">\r\n            <strong>${escHtml(v.vehicleNumber || loc.vehicle_id)}</strong>\r\n            <div>Driver: ${escHtml(v.driverName || \"-\")}</div>\r\n            <div style=\"font-weight:800;color:${status === \"live\" ? \"#16794f\" : \"#9a6700\"}\">${escHtml(status.toUpperCase())}</div>\r\n            <div>Updated: ${escHtml(formatLiveAge(loc.updated_at))}</div>\r\n            <div>Speed: ${escHtml(String(Math.round(calibratedSpeedKmh(loc.speed))))} km/h</div>\r\n            <div style=\"color:#64748b\">${escHtml(Number(loc.latitude).toFixed(5))}, ${escHtml(Number(loc.longitude).toFixed(5))}</div>\r\n        </div>`;\r\n    }).join(\"\");\r\n    clearMapMissing(adminMap, liveLocationRows.map(loc => loc.vehicle_id));\r\n    adminMap?.fitAll();\r\n}\r\n\r\nasync function refreshActiveTrips() {\r\n    activeTripRows = await activeTrips(vehicles.map(v => v.id)).catch(() => []);\r\n    renderVehicles();\r\n    await refreshAdminLiveMap();\r\n}\r\n\r\nfunction updateStats() {\r\n    document.getElementById(\"totalVehicles\").textContent     = vehicles.length;\r\n    document.getElementById(\"activeVehicles\").textContent    = vehicles.filter(v=>v.status===\"active\").length;\r\n    document.getElementById(\"maintenanceVehicles\").textContent = vehicles.filter(v=>v.status===\"maintenance\").length;\r\n    document.getElementById(\"inactiveVehicles\").textContent  = vehicles.filter(v=>v.status===\"inactive\").length;\r\n    document.getElementById(\"totalRoutes\").textContent       = routes.length;\r\n    const totalAssigned = vehicles.reduce((sum,v)=>sum+(Array.isArray(v.assignedStudentIds)?v.assignedStudentIds.length:0),0);\r\n    document.getElementById(\"totalAssigned\").textContent     = totalAssigned;\r\n    const heroActive = document.getElementById(\"heroActiveVehicles\");\r\n    const heroAssigned = document.getElementById(\"heroAssignedStudents\");\r\n    const heroRoutes = document.getElementById(\"heroSavedRoutes\");\r\n    if (heroActive) heroActive.textContent = String(vehicles.filter(v=>v.status===\"active\").length);\r\n    if (heroAssigned) heroAssigned.textContent = String(totalAssigned);\r\n    if (heroRoutes) heroRoutes.textContent = String(routes.length);\r\n}\r\n\r\nfunction statusBadge(s) {\r\n    if (s===\"active\")      return '<span class=\"pill active\">ACTIVE</span>';\r\n    if (s===\"maintenance\") return '<span class=\"pill maintenance\">MAINTENANCE</span>';\r\n    return '<span class=\"pill inactive\">INACTIVE</span>';\r\n}\r\n\r\nfunction formatVehicleRoute(v) {\r\n    const idPart = v.routeId ? `<span class=\"route-id-badge\" style=\"font-size:13px;\">${escHtml(v.routeId)}</span> ` : \"\";\r\n    if (v.routeFrom && v.routeTo) {\r\n        const via = Array.isArray(v.routeVia) ? v.routeVia : [];\r\n        const segs = [escHtml(v.routeFrom), ...via.map(s=>escHtml(s)), escHtml(v.routeTo)];\r\n        const extra = v.routeName && v.routeName!==`${v.routeFrom} - ${v.routeTo}` ? ` (${escHtml(v.routeName)})` : \"\";\r\n        return `${idPart}${segs.join(\" - \")}${extra}`;\r\n    }\r\n    return `${idPart}${escHtml(v.routeName||\"-\")}`;\r\n}\r\n\r\nfunction expiryWarning(dateStr) {\r\n    if (!dateStr) return \"\";\r\n    const d = new Date(dateStr);\r\n    const now = new Date();\r\n    const diff = Math.ceil((d - now) / (1000*60*60*24));\r\n    const alertIco = `<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" style=\"vertical-align:-2px;margin-right:4px\" aria-hidden=\"true\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>`;\r\n    if (diff < 0) return `<span style=\"color:#dc2626;font-weight:700;display:inline-flex;align-items:center;\">${alertIco}Expired</span>`;\r\n    if (diff <= 30) return `<span style=\"color:#d97706;font-weight:700;display:inline-flex;align-items:center;\">${alertIco}Expiring in ${diff}d</span>`;\r\n    return \"\";\r\n}\r\n\r\nfunction renderVehicles() {\r\n    vehicleListEl.innerHTML = \"\";\r\n    if (!filteredVehicles.length) { vehicleListEl.innerHTML = '<div class=\"empty\">No vehicles found.</div>'; return; }\r\n    filteredVehicles.forEach(v => {\r\n        const row = document.createElement(\"div\");\r\n        const assigned = Array.isArray(v.assignedStudentIds) ? v.assignedStudentIds.length : 0;\r\n        const activeTrip = activeTripRows.find(t => t.vehicle_id === v.id);\r\n        const trackingOn = Boolean(activeTrip);\r\n        row.className = `vehicle-card ${trackingOn ? \"is-tracking\" : \"\"}`;\r\n        const compliance = `\r\n            Permit: ${escHtml(v.permitExpiry||\"-\")} ${expiryWarning(v.permitExpiry)}\r\n            &nbsp;|&nbsp; Insurance: ${escHtml(v.insuranceExpiry||\"-\")} ${expiryWarning(v.insuranceExpiry)}\r\n            &nbsp;|&nbsp; Fitness: ${escHtml(v.fitnessExpiry||\"-\")} ${expiryWarning(v.fitnessExpiry)}\r\n        `;\r\n        row.innerHTML = `\r\n            <div class=\"meta\">\r\n                <div class=\"vehicle-title\">\r\n                <strong>${escHtml(v.vehicleNumber || \"Vehicle\")}</strong>\r\n                ${statusBadge(v.status)}\r\n                <span class=\"pill ${trackingOn ? \"active\" : \"inactive\"}\">${trackingOn ? \"TRACKING ON\" : \"TRACKING OFF\"}</span>\r\n                <span class=\"students-count-badge\">${assigned} student${assigned!==1?\"s\":\"\"}</span>\r\n                </div>\r\n                <div class=\"vehicle-meta-grid\">\r\n                    <div class=\"vehicle-meta-box\"><small>Vehicle</small><span>${escHtml(v.vehicleType || \"-\")} ${v.vehicleModel ? `- ${escHtml(v.vehicleModel)}` : \"\"}</span></div>\r\n                    <div class=\"vehicle-meta-box\"><small>Capacity</small><span>${escHtml(String(v.capacity || 0))} seats</span></div>\r\n                    <div class=\"vehicle-meta-box\"><small>Driver</small><span>${escHtml(v.driverName || \"-\")} ${v.driverPhone ? `- ${escHtml(v.driverPhone)}` : \"\"}</span></div>\r\n                    <div class=\"vehicle-meta-box\"><small>Driver Login</small><span>${escHtml(v.driverEmail || \"Not set\")}</span></div>\r\n                    <div class=\"vehicle-meta-box\" style=\"grid-column: span 2;\"><small>Route</small><span>${formatVehicleRoute(v)}</span></div>\r\n                    <div class=\"vehicle-compliance\">${compliance}</div>\r\n                    ${v.notes ? `<div class=\"vehicle-meta-box\" style=\"grid-column:1/-1;\"><small>Notes</small><span>${escHtml(v.notes)}</span></div>` : \"\"}\r\n                </div>\r\n            </div>\r\n            <div class=\"action-col\">\r\n                ${trackingOn\r\n                    ? `<button class=\"btn-danger\" onclick=\"stopVehicleTracking('${escHtml(v.id)}')\">${ICONS.stop}Stop Tracking</button>`\r\n                    : `<button class=\"btn-primary\" onclick=\"startVehicleTracking('${escHtml(v.id)}')\">${ICONS.play}Start Tracking</button>`}\r\n                <button class=\"btn-purple\" onclick=\"openAssignModal('${escHtml(v.id)}')\">${ICONS.users}Assign Students</button>\r\n                <button class=\"btn-success\" onclick=\"editVehicle('${escHtml(v.id)}')\">${ICONS.edit}Edit</button>\r\n                <button class=\"btn-danger\"  onclick=\"deleteVehicle('${escHtml(v.id)}')\">${ICONS.trash}Delete</button>\r\n            </div>`;\r\n        vehicleListEl.appendChild(row);\r\n    });\r\n}\r\n\r\nwindow.startVehicleTracking = async (vehicleId) => {\r\n    const v = vehicles.find(x => x.id === vehicleId);\r\n    if (!v) return;\r\n    const actionButton = currentActionButton();\r\n    if (!confirm(`Start tracking for ${v.vehicleNumber || vehicleId}? Driver phone will begin sending GPS if logged in and permission is granted.`)) return;\r\n    try {\r\n        setButtonBusy(actionButton, true, \"Starting...\");\r\n        setPageBusy(true, \"Starting tracking...\", \"Opening active trip and preparing live GPS sync.\");\r\n        const synced = await safeUpsertTrackingVehicle(vehicleId, v);\r\n        if (!synced) {\r\n            alert(\"Live tracking sync complete nahi ho paaya. Vehicle save karke dobara Start Tracking try karo.\");\r\n            return;\r\n        }\r\n        await startTrip(vehicleId);\r\n        showToast(\"Tracking started. Admin map is watching for the driver's live GPS now.\", \"success\");\r\n        await refreshActiveTrips();\r\n        await refreshAdminLiveMap();\r\n        queueLiveMapRefresh();\r\n    } catch (error) {\r\n        console.error(error);\r\n        if (isTransportSetupMissing(error)) {\r\n            alert(\"Supabase transport migration apply nahi hui hai. Transport tables/RPC missing hain, isliye Start Tracking nahi chal sakta.\");\r\n        } else if (isTransportAccessDenied(error)) {\r\n            alert(\"Live tracking access denied hai. Admin account se dobara login karo, phir Start Tracking try karo.\");\r\n        } else {\r\n            alert(error.message || \"Could not start tracking. Vehicle/driver sync check karke dobara try karo.\");\r\n        }\r\n    } finally {\r\n        setButtonBusy(actionButton, false);\r\n        setPageBusy(false);\r\n    }\r\n};\r\n\r\nwindow.stopVehicleTracking = async (vehicleId) => {\r\n    const v = vehicles.find(x => x.id === vehicleId);\r\n    if (!v) return;\r\n    const actionButton = currentActionButton();\r\n    if (!confirm(`Stop tracking for ${v.vehicleNumber || vehicleId}?`)) return;\r\n    try {\r\n        setButtonBusy(actionButton, true, \"Stopping...\");\r\n        setPageBusy(true, \"Stopping tracking...\", \"Closing active trip for this vehicle.\");\r\n        await stopTrip(vehicleId);\r\n        showToast(\"Tracking stopped.\", \"success\");\r\n        await refreshActiveTrips();\r\n        await refreshAdminLiveMap();\r\n    } catch (error) {\r\n        console.error(error);\r\n        alert(error.message || \"Could not stop tracking.\");\r\n    } finally {\r\n        setButtonBusy(actionButton, false);\r\n        setPageBusy(false);\r\n    }\r\n};\r\n\r\nfunction applyFilters() {\r\n    const q = searchInput.value.trim().toLowerCase();\r\n    const s = statusFilter.value, t = typeFilter.value;\r\n    filteredVehicles = vehicles.filter(v => {\r\n        const viaMatch = (Array.isArray(v.routeVia)?v.routeVia:[]).some(x=>(x||\"\").toLowerCase().includes(q));\r\n        const matchQ =\r\n            (v.vehicleNumber||\"\").toLowerCase().includes(q) ||\r\n            (v.routeName||\"\").toLowerCase().includes(q) ||\r\n            (v.routeId||\"\").toLowerCase().includes(q) ||\r\n            (v.routeFrom||\"\").toLowerCase().includes(q) ||\r\n            (v.routeTo||\"\").toLowerCase().includes(q) || viaMatch ||\r\n            (v.driverName||\"\").toLowerCase().includes(q) ||\r\n            (v.driverPhone||\"\").toLowerCase().includes(q) ||\r\n            (v.driverEmail||\"\").toLowerCase().includes(q);\r\n        return matchQ && (s===\"all\"||v.status===s) && (t===\"all\"||v.vehicleType===t);\r\n    });\r\n    renderVehicles();\r\n}\r\nsearchInput.addEventListener(\"input\", applyFilters);\r\nstatusFilter.addEventListener(\"change\", applyFilters);\r\ntypeFilter.addEventListener(\"change\", applyFilters);\r\n\r\nwindow.editVehicle = (id) => {\r\n    const v = vehicles.find(x => x.id===id); if (!v) return;\r\n    editingVehicleId = id;\r\n    document.getElementById(\"vehicleNumber\").value   = v.vehicleNumber||\"\";\r\n    document.getElementById(\"vehicleType\").value     = v.vehicleType||\"\";\r\n    document.getElementById(\"vehicleModel\").value    = v.vehicleModel||\"\";\r\n    document.getElementById(\"capacity\").value        = v.capacity||\"\";\r\n    document.getElementById(\"driverName\").value      = v.driverName||\"\";\r\n    document.getElementById(\"driverPhone\").value     = v.driverPhone||\"\";\r\n    document.getElementById(\"driverEmail\").value     = v.driverEmail||\"\";\r\n    document.getElementById(\"driverPassword\").value  = \"\";\r\n    populateRouteDropdown(); vehicleRouteSelect.value = v.routeId||\"\";\r\n    document.getElementById(\"routeName\").value       = v.routeName||\"\";\r\n    document.getElementById(\"permitExpiry\").value    = v.permitExpiry||\"\";\r\n    document.getElementById(\"insuranceExpiry\").value = v.insuranceExpiry||\"\";\r\n    document.getElementById(\"fitnessExpiry\").value   = v.fitnessExpiry||\"\";\r\n    document.getElementById(\"vehicleStatus\").value   = v.status||\"active\";\r\n    document.getElementById(\"notes\").value           = v.notes||\"\";\r\n    formTitleEl.textContent = \"Edit Vehicle\";\r\n    saveBtnEl.innerHTML     = saveVehicleButtonHtml(\"Update Vehicle\");\r\n    window.scrollTo({ top: 0, behavior: \"smooth\" });\r\n};\r\n\r\nwindow.deleteVehicle = async (id) => {\r\n    const actionButton = currentActionButton();\r\n    if (!confirm(\"Delete this vehicle?\")) return;\r\n    try {\r\n        setButtonBusy(actionButton, true, \"Deleting...\");\r\n        setPageBusy(true, \"Deleting vehicle...\", \"Removing record and refreshing transport workspace.\");\r\n        await deleteDoc(doc(db, \"schools\", adminId, \"vehicles\", id));\r\n        if (editingVehicleId===id) resetForm();\r\n        await loadVehicles();\r\n        showToast(\"Vehicle deleted.\", \"info\");\r\n    } catch(e) { alert(\"Failed to delete.\"); }\r\n    finally {\r\n        setButtonBusy(actionButton, false);\r\n        setPageBusy(false);\r\n    }\r\n};\r\n\r\nwindow.resetForm = () => {\r\n    editingVehicleId = null; vehicleForm.reset();\r\n    document.getElementById(\"driverPassword\").value = \"\";\r\n    document.getElementById(\"vehicleStatus\").value = \"active\";\r\n    vehicleRouteSelect.value = \"\"; populateRouteDropdown();\r\n    formTitleEl.textContent = \"Add Vehicle\"; saveBtnEl.innerHTML = saveVehicleButtonHtml(\"Save Vehicle\");\r\n};\r\n\r\nwindow.logout = async () => {\r\n    try { await signOut(auth); window.location.href = \"#/index.html\"; }\r\n    catch(e) { alert(\"Logout failed.\"); }\r\n};\r\n\r\ndocument.getElementById(\"studentSearchInput\").addEventListener(\"keydown\", e => {\r\n    if (e.key === \"Enter\") { e.preventDefault(); searchStudents(); }\r\n});\r\nrouteLookupInput.addEventListener(\"keydown\", e => {\r\n    if (e.key === \"Enter\") { e.preventDefault(); fetchRouteById(); }\r\n});\r\n</script>\r\n<script type=\"module\" src=\"access-control.js\"></script>\r\n  <script src=\"schoolix-polish.js\" defer></script>\r\n  <script src=\"admin-shell.js?v=navbar-20260721\" defer></script>\r\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\nhtml.sx-page-loading,\nhtml.sx-page-loading body {\n  min-height: 100%;\n  background: #f8fafc !important;\n}\nhtml.sx-page-loading body::before,\nhtml.sx-page-loading body::after {\n  visibility: hidden !important;\n}\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\n  visibility: hidden !important;\n}\n.sx-page-loader {\n  position: fixed;\n  inset: 0;\n  z-index: 2147482500;\n  display: flex;\n  align-items: stretch;\n  justify-content: stretch;\n  background: #f8fafc;\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\n  overflow: hidden;\n}\n.sx-page-loader.is-hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n.sx-page-loader .dots-container {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100vw;\n  height: 100vh;\n  padding: 0;\n  margin: 0;\n  overflow: hidden;\n  background: #f8fafc;\n}\n.sx-page-loader .dots-container::before,\n.sx-page-loader .dots-container::after,\n.sx-page-loader .dot {\n  display: none !important;\n}\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":""},{"tag":"link","attributes":{"rel":"stylesheet","href":"admin-shell.css?v=navbar-20260721"},"text":""}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"src":"school-branding.js"},"text":""},{"attributes":{"type":"module"},"text":"\r\nimport { initializeApp } from \"./firebase-compat.js\";\r\nimport { getAuth, onAuthStateChanged, signOut, createUserWithEmailAndPassword } from \"./firebase-compat.js\";\r\nimport {\r\n    getFirestore, doc, getDoc, collection, getDocs,\r\n    addDoc, updateDoc, deleteDoc, setDoc, serverTimestamp,\r\n    query, where, arrayUnion, arrayRemove\r\n} from \"./firebase-compat.js\";\r\nimport { calibratedSpeedKmh, createVehicleMap, locationStatus } from \"./schoolix-maplibre.js\";\r\nimport { activeTrips, assignDriver, deactivateStudentTransport, isTransportAccessDenied, isTransportDriverReferenceMissing, isTransportSetupMissing, liveLocations, startTrip, stopTrip, subscribeTransport, upsertDriver, upsertStudentTransport, upsertVehicle } from \"./schoolix-transport.js\";\r\n\r\nconst firebaseConfig = {\r\n    apiKey: \"@secret:GOOGLE_API_KEY\",\r\n    authDomain: \"schoolix-48107.firebaseapp.com\",\r\n    projectId: \"schoolix-48107\",\r\n    storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n    messagingSenderId: \"133937954491\",\r\n    appId: \"1:133937954491:web:69d8064422617eb8c4339e\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\r\nconst db = getFirestore(app);\r\n\r\nconst vehicleForm   = document.getElementById(\"vehicleForm\");\r\nconst routeForm     = document.getElementById(\"routeForm\");\r\nconst vehicleListEl = document.getElementById(\"vehicleList\");\r\nconst routeListEl   = document.getElementById(\"routeList\");\r\nconst searchInput   = document.getElementById(\"searchInput\");\r\nconst statusFilter  = document.getElementById(\"statusFilter\");\r\nconst typeFilter    = document.getElementById(\"typeFilter\");\r\nconst formTitleEl   = document.getElementById(\"formTitle\");\r\nconst saveBtnEl     = document.getElementById(\"saveBtn\");\r\nconst vehicleRouteSelect = document.getElementById(\"vehicleRouteSelect\");\r\nconst routeLookupInput   = document.getElementById(\"routeLookupInput\");\r\nconst routeLookupResult  = document.getElementById(\"routeLookupResult\");\r\n\r\nlet adminId = null;\r\nlet vehicles = [];\r\nlet routes = [];\r\nlet allStudents = [];\r\nlet filteredVehicles = [];\r\nlet editingVehicleId = null;\r\nlet assigningVehicleId = null;\r\nlet adminMap = null;\r\nlet liveLocationRows = [];\r\nlet activeTripRows = [];\r\nlet vehicleListLoading = true;\r\nlet routeListLoading = true;\r\nlet liveMapRefreshTimer = 0;\r\n\r\nwindow.SchoolixTransportLiveRefreshMs = 3000;\r\n\r\nconst ICONS = {\r\n    search: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"M21 21l-4.3-4.3\"/></svg>',\r\n    users: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>',\r\n    edit: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M12 20h9\"/><path d=\"M16.5 3.5a2.1 2.1 0 0 1 3 3L7 19l-4 1 1-4Z\"/></svg>',\r\n    trash: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M3 6h18\"/><path d=\"M8 6V4h8v2\"/><path d=\"M19 6l-1 14H6L5 6\"/></svg>',\r\n    route: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><circle cx=\"6\" cy=\"19\" r=\"3\"/><path d=\"M9 19h8.5a3.5 3.5 0 0 0 0-7H8a3 3 0 0 1 0-6h10\"/><circle cx=\"18\" cy=\"5\" r=\"3\"/></svg>',\r\n    bus: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M8 6v6\"/><path d=\"M15 6v6\"/><path d=\"M2 12h19.6\"/><path d=\"M18 18h3s.5-1.7.8-3.2c.1-.7.2-1.4.2-2.1V8a3 3 0 0 0-3-3H5a3 3 0 0 0-3 3v10h3\"/><circle cx=\"7\" cy=\"18\" r=\"2\"/><circle cx=\"16\" cy=\"18\" r=\"2\"/></svg>',\r\n    play: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polygon points=\"6 3 20 12 6 21 6 3\"/></svg>',\r\n    stop: '<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"6\" y=\"6\" width=\"12\" height=\"12\" rx=\"2\"/></svg>'\r\n};\r\n\r\nfunction escHtml(s) {\r\n    if (s == null || s === \"\") return \"\";\r\n    return String(s).replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\").replace(/\"/g,\"&quot;\");\r\n}\r\n\r\nfunction skeletonCards(count = 3) {\r\n    return Array.from({ length: count }, () => `\r\n        <div class=\"sx-skeleton-card\" aria-hidden=\"true\">\r\n            <div class=\"sx-skeleton-line w60\"></div>\r\n            <div class=\"sx-skeleton-line w80\"></div>\r\n            <div class=\"sx-skeleton-line\"></div>\r\n        </div>\r\n    `).join(\"\");\r\n}\r\n\r\nfunction setPageBusy(visible, title = \"Loading transport workspace...\", text = \"Fetching routes, vehicles and live tracking status.\") {\r\n    const overlay = document.getElementById(\"transportPageBusy\");\r\n    if (!overlay) return;\r\n    document.getElementById(\"transportBusyTitle\").textContent = title;\r\n    document.getElementById(\"transportBusyText\").textContent = text;\r\n    overlay.classList.toggle(\"is-visible\", Boolean(visible));\r\n    overlay.setAttribute(\"aria-hidden\", String(!visible));\r\n}\r\n\r\nfunction setButtonBusy(button, busy, label = \"Working...\") {\r\n    if (!button) return;\r\n    if (busy) {\r\n        button.dataset.originalHtml = button.dataset.originalHtml || button.innerHTML;\r\n        button.disabled = true;\r\n        button.innerHTML = `<span class=\"sx-spinner\" style=\"width:16px;height:16px;margin:0;border-width:2px;\"></span>${escHtml(label)}`;\r\n    } else {\r\n        button.disabled = false;\r\n        if (button.dataset.originalHtml) {\r\n            button.innerHTML = button.dataset.originalHtml;\r\n            delete button.dataset.originalHtml;\r\n        }\r\n        if (button.id === \"saveBtn\" && !editingVehicleId) {\r\n            button.innerHTML = saveVehicleButtonHtml(\"Save Vehicle\");\r\n        }\r\n    }\r\n}\r\n\r\nfunction saveVehicleButtonHtml(label = \"Save Vehicle\") {\r\n    return `<svg class=\"icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><path d=\"M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z\"/><path d=\"M17 21v-8H7v8\"/><path d=\"M7 3v5h8\"/></svg>${escHtml(label)}`;\r\n}\r\n\r\nfunction currentActionButton() {\r\n    const active = document.activeElement;\r\n    return active?.tagName === \"BUTTON\" ? active : null;\r\n}\r\n\r\nfunction clearMapMissing(mapApi, vehicleIds = []) {\r\n    if (typeof mapApi?.clearMissing === \"function\") {\r\n        mapApi.clearMissing(vehicleIds);\r\n        return;\r\n    }\r\n    const keep = new Set(vehicleIds.map((id) => String(id)));\r\n    mapApi?.markers?.forEach?.((entry, id) => {\r\n        if (!keep.has(String(id))) {\r\n            entry?.marker?.remove?.();\r\n            mapApi.markers.delete(id);\r\n        }\r\n    });\r\n}\r\n\r\nvehicleListEl.innerHTML = skeletonCards(4);\r\nrouteListEl.innerHTML = skeletonCards(2);\r\ndocument.getElementById(\"adminLiveVehicleList\").innerHTML = skeletonCards(3);\r\n\r\nonAuthStateChanged(auth, async (user) => {\r\n    setPageBusy(true);\r\n    if (!user) { window.location.href = \"#/index.html\"; return; }\r\n    try {\r\n        const userDoc = await getDoc(doc(db, \"users\", user.uid));\r\n        if (!userDoc.exists() || userDoc.data().role !== \"admin\") {\r\n            alert(\"Access denied.\");\r\n            window.location.href = \"#/index.html\";\r\n            return;\r\n        }\r\n        adminId = user.uid;\r\n        await loadRoutes();\r\n        await loadVehicles();\r\n        adminMap = await createVehicleMap(document.getElementById(\"adminLiveMap\"), { zoom: 12, recenterLabel: \"Show active vehicles\" });\r\n        await loadAllStudents();\r\n        await refreshActiveTrips();\r\n        await refreshAdminLiveMap();\r\n        subscribeTransport(\"schoolix_vehicle_live_locations\", `school_id=eq.${adminId}`, refreshAdminLiveMap, refreshAdminLiveMap);\r\n        subscribeTransport(\"schoolix_transport_trips\", `school_id=eq.${adminId}`, refreshActiveTrips, refreshActiveTrips);\r\n    } finally {\r\n        setPageBusy(false);\r\n    }\r\n});\r\n\r\n/* Students cache */\r\nasync function loadAllStudents() {\r\n    try {\r\n        const snap = await getDocs(collection(db, \"schools\", adminId, \"students\"));\r\n        allStudents = snap.docs.map(d => ({ id: d.id, ...d.data() }));\r\n    } catch(e) { console.error(\"Load students failed:\", e); }\r\n}\r\n\r\n/* Assign modal */\r\nwindow.openAssignModal = async (vehicleId) => {\r\n    assigningVehicleId = vehicleId;\r\n    const v = vehicles.find(x => x.id === vehicleId);\r\n    if (!v) return;\r\n\r\n    document.getElementById(\"assignModalTitle\").textContent =\r\n        `Assign Students - ${v.vehicleNumber}`;\r\n    document.getElementById(\"assignModalSub\").textContent =\r\n        `${v.vehicleType} - Driver: ${v.driverName} - Capacity: ${v.capacity} seats`;\r\n    document.getElementById(\"studentSearchInput\").value = \"\";\r\n    document.getElementById(\"studentSearchResults\").innerHTML =\r\n        `<div class=\"empty\" style=\"font-size:13px;\">Student dhundho upar se - naam ya ID daalo.</div>`;\r\n\r\n    document.getElementById(\"assignModal\").classList.add(\"open\");\r\n    await renderAssignedStudents(v);\r\n};\r\n\r\nwindow.closeAssignModal = () => {\r\n    document.getElementById(\"assignModal\").classList.remove(\"open\");\r\n    assigningVehicleId = null;\r\n};\r\n\r\ndocument.getElementById(\"assignModal\").addEventListener(\"click\", function(e) {\r\n    if (e.target === this) closeAssignModal();\r\n});\r\n\r\nasync function renderAssignedStudents(v) {\r\n    const list  = document.getElementById(\"assignedStudentsList\");\r\n    const count = document.getElementById(\"assignedCount\");\r\n    const assigned = Array.isArray(v.assignedStudentIds) ? v.assignedStudentIds : [];\r\n    count.textContent = assigned.length;\r\n\r\n    if (!assigned.length) {\r\n        list.innerHTML = `<div class=\"empty\" style=\"font-size:13px;\">Abhi koi student assign nahi hai.</div>`;\r\n        return;\r\n    }\r\n\r\n    list.innerHTML = `<div class=\"loading-msg\">Loading assigned students...</div>`;\r\n\r\n    // Get student details for assigned IDs\r\n    const items = assigned.map(sid => {\r\n        const s = allStudents.find(st => st.studentId === sid || st.id === sid);\r\n        return s || { studentId: sid, name: \"Unknown Student\", class: \"-\", section: \"\" };\r\n    });\r\n\r\n    // Get student tracking data\r\n    const studentTracking = v.studentTracking || {};\r\n\r\n    list.innerHTML = items.map(s => {\r\n        const sid = s.studentId || s.id;\r\n        const tracking = studentTracking[sid] || {};\r\n        \r\n        return `\r\n        <div class=\"assigned-item\" style=\"flex-direction:column;align-items:flex-start;gap:12px;padding:14px;\">\r\n            <div class=\"ai-info\" style=\"width:100%;\">\r\n                <strong>${escHtml(s.name)}</strong>\r\n                <span>ID: ${escHtml(sid)} - Class: ${escHtml(s.class||\"-\")}${s.section ? \"-\"+escHtml(s.section) : \"\"}</span>\r\n            </div>\r\n            <div style=\"width:100%;display:grid;grid-template-columns:1fr 1fr;gap:8px;\">\r\n                <div style=\"background:#ede9fe;border:1px solid #c4b5fd;border-radius:8px;padding:10px;\">\r\n                    <div style=\"font-size:11px;font-weight:700;color:#5b21b6;text-transform:uppercase;margin-bottom:6px;\">Pickup Time</div>\r\n                    <input type=\"time\" style=\"width:100%;padding:6px;border:1px solid #c4b5fd;border-radius:6px;font-size:12px;\" \r\n                        id=\"pickup_${escHtml(sid)}\" value=\"${tracking.pickupTime || ''}\" \r\n                        onchange=\"updateStudentTracking('${escHtml(sid)}', 'pickupTime', this.value)\">\r\n                    <div style=\"font-size:11px;font-weight:700;color:#5b21b6;text-transform:uppercase;margin:12px 0 6px;\">Pickup Place</div>\r\n                    <input type=\"text\" placeholder=\"Enter pickup place\" style=\"width:100%;padding:8px;border:1px solid #c4b5fd;border-radius:6px;font-size:12px;\" \r\n                        id=\"pickupPlace_${escHtml(sid)}\" value=\"${escHtml(tracking.pickupPlace || '')}\" \r\n                        onchange=\"updateStudentTracking('${escHtml(sid)}', 'pickupPlace', this.value)\">\r\n                </div>\r\n                <div style=\"background:#dcfce7;border:1px solid #86efac;border-radius:8px;padding:10px;\">\r\n                    <div style=\"font-size:11px;font-weight:700;color:#166534;text-transform:uppercase;margin-bottom:6px;\">Drop-off Time</div>\r\n                    <input type=\"time\" style=\"width:100%;padding:6px;border:1px solid #86efac;border-radius:6px;font-size:12px;\" \r\n                        id=\"dropoff_${escHtml(sid)}\" value=\"${tracking.dropoffTime || ''}\" \r\n                        onchange=\"updateStudentTracking('${escHtml(sid)}', 'dropoffTime', this.value)\">\r\n                    <div style=\"font-size:11px;font-weight:700;color:#166534;text-transform:uppercase;margin:12px 0 6px;\">Drop-off Place</div>\r\n                    <input type=\"text\" placeholder=\"Enter drop-off place\" style=\"width:100%;padding:8px;border:1px solid #86efac;border-radius:6px;font-size:12px;\" \r\n                        id=\"dropoffPlace_${escHtml(sid)}\" value=\"${escHtml(tracking.dropoffPlace || '')}\" \r\n                        onchange=\"updateStudentTracking('${escHtml(sid)}', 'dropoffPlace', this.value)\">\r\n                </div>\r\n            </div>\r\n            <button type=\"button\" class=\"btn-danger\" style=\"padding:6px 12px;font-size:12px;width:100%;\"\r\n                onclick=\"removeStudentFromVehicle('${escHtml(sid)}')\">Remove Student</button>\r\n        </div>\r\n    `;\r\n    }).join(\"\");\r\n}\r\n\r\nwindow.searchStudents = async () => {\r\n    const q = document.getElementById(\"studentSearchInput\").value.trim().toLowerCase();\r\n    const resultsEl = document.getElementById(\"studentSearchResults\");\r\n\r\n    if (!q) {\r\n        resultsEl.innerHTML = `<div class=\"empty\" style=\"font-size:13px;\">Kuch type karo phir search karo.</div>`;\r\n        return;\r\n    }\r\n\r\n    const v = vehicles.find(x => x.id === assigningVehicleId);\r\n    const alreadyAssigned = v ? (Array.isArray(v.assignedStudentIds) ? v.assignedStudentIds : []) : [];\r\n\r\n    const matches = allStudents.filter(s =>\r\n        (s.name || \"\").toLowerCase().includes(q) ||\r\n        (s.studentId || \"\").toLowerCase().includes(q) ||\r\n        (s.id || \"\").toLowerCase().includes(q)\r\n    );\r\n\r\n    if (!matches.length) {\r\n        resultsEl.innerHTML = `<div class=\"empty\" style=\"font-size:13px;\">Koi student nahi mila \"${escHtml(q)}\" ke liye.</div>`;\r\n        return;\r\n    }\r\n\r\n    resultsEl.innerHTML = `<div class=\"student-search-result\">${matches.slice(0, 10).map(s => {\r\n        const sid = s.studentId || s.id;\r\n        const isAssigned = alreadyAssigned.includes(sid);\r\n        return `<div class=\"sr-item\">\r\n            <div class=\"sr-info\">\r\n                <strong>${escHtml(s.name)}</strong>\r\n                <span>ID: ${escHtml(sid)} - Class: ${escHtml(s.class||\"-\")}${s.section?\"-\"+escHtml(s.section):\"\"} - ${escHtml(s.phone||\"\")}</span>\r\n            </div>\r\n            ${isAssigned\r\n                ? `<span class=\"pill active\" style=\"margin-left:0;white-space:nowrap;display:inline-flex;align-items:center;gap:5px;\"><svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M20 6L9 17l-5-5\"/></svg>Assigned</span>`\r\n                : `<button type=\"button\" class=\"btn-teal\" style=\"padding:6px 12px;font-size:12px;white-space:nowrap;\"\r\n                    onclick=\"assignStudentToVehicle('${escHtml(sid)}', '${escHtml(s.name)}')\">Assign</button>`\r\n            }\r\n        </div>`;\r\n    }).join(\"\")}</div>`;\r\n};\r\n\r\nwindow.assignStudentToVehicle = async (studentId, studentName) => {\r\n    if (!assigningVehicleId || !studentId) return;\r\n    try {\r\n        const v = vehicles.find(x => x.id === assigningVehicleId);\r\n        if (!v) return;\r\n        const vRef = doc(db, \"schools\", adminId, \"vehicles\", assigningVehicleId);\r\n        await updateDoc(vRef, {\r\n            assignedStudentIds: arrayUnion(studentId),\r\n            updatedAt: serverTimestamp()\r\n        });\r\n        const transportSynced = await upsertStudentTransport({\r\n            school_id: adminId,\r\n            student_id: studentId,\r\n            vehicle_id: assigningVehicleId,\r\n            route_id: v.routeId || null,\r\n            active: true,\r\n            updated_at: new Date().toISOString()\r\n        }).then(() => true).catch(error => {\r\n            console.warn(\"Student transport sync failed\", error);\r\n            return false;\r\n        });\r\n\r\n        // Also update student doc with vehicleId for easy reverse lookup\r\n        const sQuery = query(collection(db, \"schools\", adminId, \"students\"),\r\n            where(\"studentId\", \"==\", studentId));\r\n        const sSnap = await getDocs(sQuery);\r\n        if (!sSnap.empty) {\r\n            await updateDoc(doc(db, \"schools\", adminId, \"students\", sSnap.docs[0].id), {\r\n                assignedVehicleId: assigningVehicleId\r\n            });\r\n        }\r\n\r\n        showToast(\r\n            transportSynced ? `${studentName} assigned successfully!` : `${studentName} assigned. Live tracking sync pending.`,\r\n            transportSynced ? \"success\" : \"info\"\r\n        );\r\n        await loadVehicles();\r\n        await loadAllStudents();\r\n        const updatedV = vehicles.find(x => x.id === assigningVehicleId);\r\n        if (updatedV) {\r\n            await renderAssignedStudents(updatedV);\r\n            document.getElementById(\"assignedCount\").textContent =\r\n                (updatedV.assignedStudentIds || []).length;\r\n        }\r\n        // Refresh search results\r\n        await searchStudents();\r\n    } catch(e) {\r\n        console.error(e);\r\n        showToast(\"Assignment failed!\", \"error\");\r\n    }\r\n};\r\n\r\nwindow.updateStudentTracking = async (studentId, field, value) => {\r\n    if (!assigningVehicleId || !studentId) return;\r\n    try {\r\n        const v = vehicles.find(x => x.id === assigningVehicleId);\r\n        if (!v) return;\r\n        \r\n        const tracking = v.studentTracking || {};\r\n        if (!tracking[studentId]) tracking[studentId] = {};\r\n        tracking[studentId][field] = value;\r\n        \r\n        const vRef = doc(db, \"schools\", adminId, \"vehicles\", assigningVehicleId);\r\n        await updateDoc(vRef, {\r\n            studentTracking: tracking,\r\n            updatedAt: serverTimestamp()\r\n        });\r\n        \r\n        const fieldLabels = {\r\n            pickupTime: 'Pickup time',\r\n            dropoffTime: 'Drop-off time',\r\n            pickupPlace: 'Pickup place',\r\n            dropoffPlace: 'Drop-off place'\r\n        };\r\n        showToast(`${fieldLabels[field] || 'Update'} saved!`, \"success\");\r\n        await loadVehicles();\r\n    } catch(e) {\r\n        console.error(e);\r\n        showToast(\"Update failed!\", \"error\");\r\n    }\r\n};\r\n\r\nwindow.removeStudentFromVehicle = async (studentId) => {\r\n    if (!assigningVehicleId || !studentId) return;\r\n    if (!confirm(`Remove student ${studentId} from this vehicle?`)) return;\r\n    try {\r\n        const v = vehicles.find(x => x.id === assigningVehicleId);\r\n        if (!v) return;\r\n        \r\n        const tracking = v.studentTracking || {};\r\n        delete tracking[studentId];\r\n        \r\n        const vRef = doc(db, \"schools\", adminId, \"vehicles\", assigningVehicleId);\r\n        await updateDoc(vRef, {\r\n            assignedStudentIds: arrayRemove(studentId),\r\n            studentTracking: tracking,\r\n            updatedAt: serverTimestamp()\r\n        });\r\n        await deactivateStudentTransport(adminId, studentId, assigningVehicleId)\r\n            .catch(error => console.warn(\"Student transport deactivate failed\", error));\r\n\r\n        // Remove from student doc too\r\n        const sQuery = query(collection(db, \"schools\", adminId, \"students\"),\r\n            where(\"studentId\", \"==\", studentId));\r\n        const sSnap = await getDocs(sQuery);\r\n        if (!sSnap.empty) {\r\n            await updateDoc(doc(db, \"schools\", adminId, \"students\", sSnap.docs[0].id), {\r\n                assignedVehicleId: \"\"\r\n            });\r\n        }\r\n\r\n        showToast(\"Student removed.\", \"info\");\r\n        await loadVehicles();\r\n        await loadAllStudents();\r\n        const updatedV = vehicles.find(x => x.id === assigningVehicleId);\r\n        if (updatedV) await renderAssignedStudents(updatedV);\r\n    } catch(e) {\r\n        console.error(e);\r\n        showToast(\"Remove failed!\", \"error\");\r\n    }\r\n};\r\n\r\n/* Toast */\r\nfunction showToast(msg, type=\"info\") {\r\n    const t = document.createElement(\"div\");\r\n    t.className = `sx-toast ${type}`;\r\n    t.setAttribute(\"role\", \"status\");\r\n    t.textContent = msg;\r\n    document.body.appendChild(t);\r\n    requestAnimationFrame(() => t.classList.add(\"is-visible\"));\r\n    setTimeout(() => {\r\n        t.classList.remove(\"is-visible\");\r\n        setTimeout(()=>t.remove(), 220);\r\n    }, 3200);\r\n}\r\n\r\n/* Routes */\r\nasync function generateRouteId() {\r\n    const snap = await getDocs(collection(db, \"schools\", adminId, \"routes\"));\r\n    const existing = new Set();\r\n    snap.forEach(d => { if (d.data().routeId) existing.add(String(d.data().routeId)); });\r\n    let id = \"\";\r\n    do { id = `RT${Math.floor(100000 + Math.random() * 900000)}`; } while (existing.has(id));\r\n    return id;\r\n}\r\n\r\nfunction getViaStopsFromForm() {\r\n    return [...document.getElementById(\"viaStopsContainer\").querySelectorAll(\".via-stop-input\")]\r\n        .map(el => el.value.trim()).filter(Boolean);\r\n}\r\n\r\nwindow.addViaStopRow = (preset = \"\") => {\r\n    const container = document.getElementById(\"viaStopsContainer\");\r\n    const row = document.createElement(\"div\");\r\n    row.className = \"via-row\";\r\n    const inp = document.createElement(\"input\");\r\n    inp.type = \"text\"; inp.className = \"via-stop-input\";\r\n    inp.placeholder = \"Via stop - area / landmark\";\r\n    if (preset) inp.value = preset;\r\n    const btn = document.createElement(\"button\");\r\n    btn.type = \"button\"; btn.className = \"btn-danger\"; btn.innerHTML = `${ICONS.trash}Remove`;\r\n    btn.addEventListener(\"click\", () => row.remove());\r\n    row.appendChild(inp); row.appendChild(btn);\r\n    container.appendChild(row); inp.focus();\r\n};\r\n\r\nfunction clearViaStopsForm() { document.getElementById(\"viaStopsContainer\").innerHTML = \"\"; }\r\n\r\nrouteForm.addEventListener(\"submit\", async (e) => {\r\n    e.preventDefault();\r\n    const submitBtn = routeForm.querySelector('button[type=\"submit\"]');\r\n    const from = document.getElementById(\"routeFrom\").value.trim();\r\n    const to   = document.getElementById(\"routeTo\").value.trim();\r\n    const notes= document.getElementById(\"routeNotes\").value.trim();\r\n    const via  = getViaStopsFromForm();\r\n    if (!from || !to) { alert(\"From and To are required.\"); return; }\r\n    try {\r\n        setButtonBusy(submitBtn, true, \"Saving route...\");\r\n        const routeId = await generateRouteId();\r\n        await addDoc(collection(db, \"schools\", adminId, \"routes\"), {\r\n            routeId, from, to, via, notes: notes||\"\",\r\n            createdAt: serverTimestamp(), updatedAt: serverTimestamp()\r\n        });\r\n        showToast(`Route saved: ${routeId}`, \"success\");\r\n        routeForm.reset(); clearViaStopsForm();\r\n        await loadRoutes();\r\n    } catch(e) { console.error(e); alert(\"Failed to save route.\"); }\r\n    finally { setButtonBusy(submitBtn, false); }\r\n});\r\n\r\nasync function loadRoutes() {\r\n    try {\r\n        if (routeListLoading) routeListEl.innerHTML = skeletonCards(2);\r\n        const snap = await getDocs(collection(db, \"schools\", adminId, \"routes\"));\r\n        routes = snap.docs.map(d => ({ id: d.id, ...d.data() }));\r\n        routeListLoading = false;\r\n        document.getElementById(\"totalRoutes\").textContent = routes.length;\r\n        const heroRoutes = document.getElementById(\"heroSavedRoutes\");\r\n        if (heroRoutes) heroRoutes.textContent = String(routes.length);\r\n        populateRouteDropdown();\r\n        renderRouteList();\r\n    } catch(e) { routeListLoading = false; routeListEl.innerHTML = '<div class=\"empty\">Failed to load routes.</div>'; }\r\n}\r\n\r\nfunction populateRouteDropdown() {\r\n    const current = vehicleRouteSelect.value;\r\n    vehicleRouteSelect.innerHTML = '<option value=\"\">- No saved route - use manual name below</option>';\r\n    routes.forEach(r => {\r\n        const via = Array.isArray(r.via) ? r.via : [];\r\n        const opt = document.createElement(\"option\");\r\n        opt.value = r.routeId;\r\n        opt.textContent = `${r.routeId}: ${r.from} - ${r.to}${via.length?\" (\"+via.length+\" via)\":\"\"}`;\r\n        opt.dataset.docId = r.id;\r\n        vehicleRouteSelect.appendChild(opt);\r\n    });\r\n    if ([...vehicleRouteSelect.options].some(o => o.value === current)) vehicleRouteSelect.value = current;\r\n}\r\n\r\nfunction renderRouteList() {\r\n    routeListEl.innerHTML = \"\";\r\n    if (!routes.length) { routeListEl.innerHTML = '<div class=\"empty\">No routes saved yet.</div>'; return; }\r\n    routes.forEach(r => {\r\n        const row = document.createElement(\"div\");\r\n        row.className = \"route-card\";\r\n        const via = Array.isArray(r.via) ? r.via : [];\r\n        const viaBlock = via.length\r\n            ? `<br><strong>Via:</strong><ol class=\"via-stops-list\">${via.map(s=>`<li>${escHtml(s)}</li>`).join(\"\")}</ol>`\r\n            : \"\";\r\n        row.innerHTML = `\r\n            <div class=\"meta\">\r\n                <strong class=\"route-id-badge\">${escHtml(r.routeId)}</strong>\r\n                <span class=\"pill active\" style=\"margin-left:8px;\">${ICONS.route}${escHtml(r.from)} - ${escHtml(r.to)}</span>\r\n                ${viaBlock}\r\n                ${r.notes ? `<br>Notes: ${escHtml(r.notes)}` : \"\"}\r\n            </div>\r\n            <div class=\"action-col\">\r\n                <button type=\"button\" class=\"btn-success\" onclick=\"useRouteLookup('${escHtml(r.routeId)}')\">${ICONS.search}Show details</button>\r\n                <button type=\"button\" class=\"btn-danger\" onclick=\"deleteRoute('${escHtml(r.id)}')\">${ICONS.trash}Delete</button>\r\n            </div>`;\r\n        routeListEl.appendChild(row);\r\n    });\r\n}\r\n\r\nwindow.fetchRouteById = async () => {\r\n    const raw = routeLookupInput.value.trim().toUpperCase();\r\n    if (!raw) { alert(\"Enter a Route ID.\"); return; }\r\n    const trigger = document.activeElement?.tagName === \"BUTTON\" ? document.activeElement : null;\r\n    try {\r\n        setButtonBusy(trigger, true, \"Fetching...\");\r\n        const q = query(collection(db, \"schools\", adminId, \"routes\"), where(\"routeId\", \"==\", raw));\r\n        const snap = await getDocs(q);\r\n        if (snap.empty) { routeLookupResult.classList.remove(\"show\"); alert(\"No route found.\"); return; }\r\n        const data = snap.docs[0].data();\r\n        document.getElementById(\"lookupRouteId\").textContent = data.routeId || raw;\r\n        document.getElementById(\"lookupFrom\").textContent   = data.from || \"-\";\r\n        document.getElementById(\"lookupTo\").textContent     = data.to || \"-\";\r\n        document.getElementById(\"lookupNotes\").textContent  = data.notes || \"-\";\r\n        const via = Array.isArray(data.via) ? data.via : [];\r\n        const viaBlock = document.getElementById(\"lookupViaBlock\");\r\n        const viaList  = document.getElementById(\"lookupViaList\");\r\n        viaList.innerHTML = \"\";\r\n        if (via.length) {\r\n            via.forEach(s => { const li = document.createElement(\"li\"); li.textContent = s; viaList.appendChild(li); });\r\n            viaBlock.style.display = \"block\";\r\n        } else { viaBlock.style.display = \"none\"; }\r\n        routeLookupResult.classList.add(\"show\");\r\n    } catch(e) { alert(\"Could not fetch route.\"); }\r\n    finally { setButtonBusy(trigger, false); }\r\n};\r\n\r\nwindow.useRouteLookup = (routeId) => {\r\n    routeLookupInput.value = routeId; fetchRouteById();\r\n    document.getElementById(\"routeLookupCard\")?.scrollIntoView({ behavior: \"smooth\", block: \"start\" });\r\n};\r\n\r\nwindow.resetRouteForm = () => { document.getElementById(\"routeForm\").reset(); clearViaStopsForm(); };\r\n\r\nwindow.deleteRoute = async (docId) => {\r\n    if (!confirm(\"Delete this route?\")) return;\r\n    try {\r\n        setPageBusy(true, \"Deleting route...\", \"Updating route list and vehicle route dropdown.\");\r\n        await deleteDoc(doc(db, \"schools\", adminId, \"routes\", docId));\r\n        await loadRoutes(); await loadVehicles();\r\n        showToast(\"Route deleted.\", \"info\");\r\n    } catch(e) { alert(\"Failed to delete.\"); }\r\n    finally { setPageBusy(false); }\r\n};\r\n\r\n/* Vehicles */\r\nfunction isUuid(value = \"\") {\r\n    return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value || \"\").trim());\r\n}\r\n\r\nfunction trackingVehiclePayload(vehicleId, v = {}) {\r\n    return {\r\n        id: vehicleId,\r\n        school_id: adminId,\r\n        vehicle_number: v.vehicleNumber || vehicleId,\r\n        vehicle_type: v.vehicleType || \"Bus\",\r\n        route_id: v.routeId || null,\r\n        driver_id: v.driverId || null,\r\n        status: v.status || \"active\",\r\n        data: {\r\n            driverName: v.driverName || \"\",\r\n            driverPhone: v.driverPhone || \"\",\r\n            driverEmail: v.driverEmail || \"\",\r\n            routeName: v.routeName || \"\",\r\n            capacity: v.capacity || 0\r\n        },\r\n        updated_at: new Date().toISOString()\r\n    };\r\n}\r\n\r\nasync function findUserByEmail(email) {\r\n    const cleanEmail = String(email || \"\").trim().toLowerCase();\r\n    if (!cleanEmail) return null;\r\n    const snap = await getDocs(query(collection(db, \"users\"), where(\"email\", \"==\", cleanEmail)));\r\n    if (!snap.empty) return { id: snap.docs[0].id, ...snap.docs[0].data() };\r\n    const authSnap = await getDocs(query(collection(db, \"users\"), where(\"authEmail\", \"==\", cleanEmail)));\r\n    if (!authSnap.empty) return { id: authSnap.docs[0].id, ...authSnap.docs[0].data() };\r\n    return null;\r\n}\r\n\r\nasync function ensureDriverLogin(vehicleId, payload) {\r\n    const email = String(payload.driverEmail || \"\").trim().toLowerCase();\r\n    const password = document.getElementById(\"driverPassword\").value.trim();\r\n    if (!email) return {};\r\n\r\n    let userProfile = await findUserByEmail(email);\r\n    let authUid = String(userProfile?.authUid || userProfile?.uid || userProfile?.id || \"\").trim();\r\n\r\n    if (!userProfile) {\r\n        if (!password || password.length < 6) {\r\n            throw new Error(\"New driver login ke liye email ke saath minimum 6 character password set karo.\");\r\n        }\r\n        const cred = await createUserWithEmailAndPassword(auth, email, password);\r\n        authUid = cred.user.uid;\r\n        userProfile = { id: authUid };\r\n    }\r\n\r\n    const driverId = String(userProfile.driverId || userProfile.transportDriverId || authUid || email).trim();\r\n    const userDocId = String(userProfile.id || authUid).trim();\r\n    const profilePayload = {\r\n        name: payload.driverName || \"Driver\",\r\n        phone: payload.driverPhone,\r\n        email,\r\n        authEmail: email,\r\n        role: \"driver\",\r\n        schoolId: adminId,\r\n        adminId,\r\n        access: true,\r\n        status: \"active\",\r\n        assignedVehicleId: vehicleId,\r\n        driverId,\r\n        transportDriverId: driverId,\r\n        updatedAt: serverTimestamp()\r\n    };\r\n\r\n    if (authUid) {\r\n        profilePayload.authUid = authUid;\r\n        profilePayload.uid = authUid;\r\n    }\r\n\r\n    await setDoc(doc(db, \"users\", userDocId), profilePayload, { merge: true });\r\n\r\n    const driverRow = {\r\n        id: driverId,\r\n        school_id: adminId,\r\n        auth_uid: isUuid(authUid) ? authUid : null,\r\n        name: payload.driverName || \"Driver\",\r\n        phone: payload.driverPhone,\r\n        email,\r\n        assigned_vehicle_id: vehicleId,\r\n        status: \"active\",\r\n        data: {\r\n            vehicleNumber: payload.vehicleNumber,\r\n            userDocId,\r\n            authUid\r\n        },\r\n        updated_at: new Date().toISOString()\r\n    };\r\n    const driverSynced = await upsertDriver(driverRow)\r\n        .then(() => assignDriver(driverId, vehicleId, adminId))\r\n        .then(() => true)\r\n        .catch(error => {\r\n            console.warn(\"Driver transport sync skipped:\", error);\r\n            return false;\r\n        });\r\n    if (!driverSynced) showToast(\"Driver login created. Live tracking sync pending.\", \"info\");\r\n\r\n    return { driverId, driverAuthUid: authUid, driverEmail: email };\r\n}\r\n\r\nasync function safeUpsertTrackingVehicle(vehicleId, payload) {\r\n    try {\r\n        await upsertVehicle(trackingVehiclePayload(vehicleId, payload));\r\n        return true;\r\n    } catch (error) {\r\n        if (isTransportDriverReferenceMissing(error) && payload?.driverId) {\r\n            console.warn(\"Vehicle driver reference missing in transport sync; starting trip without linked driver row.\", error);\r\n            const withoutDriver = { ...payload, driverId: null };\r\n            await upsertVehicle(trackingVehiclePayload(vehicleId, withoutDriver));\r\n            return true;\r\n        }\r\n        throw error;\r\n    }\r\n}\r\n\r\nvehicleForm.addEventListener(\"submit\", async (e) => {\r\n    e.preventDefault();\r\n    const submitBtn = document.getElementById(\"saveBtn\");\r\n    const selectedRouteId = vehicleRouteSelect.value.trim();\r\n    const manualRouteName = document.getElementById(\"routeName\").value.trim();\r\n    let routeName = manualRouteName || \"Unassigned route\", routeFrom = \"\", routeTo = \"\", routeVia = [];\r\n    if (selectedRouteId) {\r\n        const r = routes.find(x => x.routeId === selectedRouteId);\r\n        if (r) { routeFrom=r.from||\"\"; routeTo=r.to||\"\"; routeVia=Array.isArray(r.via)?r.via:[]; if (!routeName) routeName=`${r.from} - ${r.to}`; }\r\n    }\r\n\r\n    const payload = {\r\n        vehicleNumber:   document.getElementById(\"vehicleNumber\").value.trim().toUpperCase(),\r\n        vehicleType:     document.getElementById(\"vehicleType\").value,\r\n        vehicleModel:    document.getElementById(\"vehicleModel\").value.trim(),\r\n        capacity:        Number(document.getElementById(\"capacity\").value||0),\r\n        driverName:      document.getElementById(\"driverName\").value.trim(),\r\n        driverPhone:     document.getElementById(\"driverPhone\").value.trim(),\r\n        driverEmail:     document.getElementById(\"driverEmail\").value.trim().toLowerCase(),\r\n        routeId: selectedRouteId||\"\", routeName, routeFrom, routeTo, routeVia,\r\n        permitExpiry:    document.getElementById(\"permitExpiry\").value||\"\",\r\n        insuranceExpiry: document.getElementById(\"insuranceExpiry\").value||\"\",\r\n        fitnessExpiry:   document.getElementById(\"fitnessExpiry\").value||\"\",\r\n        status:          document.getElementById(\"vehicleStatus\").value,\r\n        notes:           document.getElementById(\"notes\").value.trim(),\r\n        updatedAt:       serverTimestamp()\r\n    };\r\n\r\n    if (!payload.vehicleNumber || !payload.vehicleType) {\r\n        alert(\"Vehicle number and vehicle type are required.\"); return;\r\n    }\r\n    if (payload.driverEmail && !payload.driverName) {\r\n        alert(\"Driver login email ke saath driver name bhi daalo.\"); return;\r\n    }\r\n    const dup = vehicles.find(v => v.vehicleNumber===payload.vehicleNumber && v.id!==editingVehicleId);\r\n    if (dup) { alert(\"Vehicle number already exists.\"); return; }\r\n\r\n    try {\r\n        setButtonBusy(submitBtn, true, editingVehicleId ? \"Updating...\" : \"Saving...\");\r\n        let vehicleId = editingVehicleId;\r\n        if (editingVehicleId) {\r\n            await updateDoc(doc(db, \"schools\", adminId, \"vehicles\", editingVehicleId), payload);\r\n            showToast(\"Vehicle updated!\", \"success\");\r\n        } else {\r\n            const vehicleRef = await addDoc(collection(db, \"schools\", adminId, \"vehicles\"), {\r\n                ...payload, assignedStudentIds: [], createdAt: serverTimestamp()\r\n            });\r\n            vehicleId = vehicleRef.id;\r\n            showToast(\"Vehicle added!\", \"success\");\r\n        }\r\n        // A vehicle record belongs to Firestore. Live tracking is an optional\n        // Supabase integration, so an unavailable migration/RLS policy must not\n        // make a successfully saved vehicle look like it failed to save.\n        let trackingPending = false;\n        try {\n            await safeUpsertTrackingVehicle(vehicleId, payload);\n        } catch (error) {\n            trackingPending = true;\n            console.warn(\"Vehicle saved, but tracking sync is pending:\", error);\n        }\n\n        if (payload.driverEmail) {\n            try {\n                const driverMeta = await ensureDriverLogin(vehicleId, payload);\n                if (Object.keys(driverMeta).length) {\n                    await updateDoc(doc(db, \"schools\", adminId, \"vehicles\", vehicleId), {\n                        ...driverMeta,\n                        updatedAt: serverTimestamp()\n                    });\n                    try {\n                        await safeUpsertTrackingVehicle(vehicleId, { ...payload, ...driverMeta });\n                    } catch (error) {\n                        trackingPending = true;\n                        console.warn(\"Vehicle saved, but driver tracking sync is pending:\", error);\n                    }\n                    showToast(\"Driver login ready for phone app.\", \"success\");\n                }\n            } catch (error) {\n                // The vehicle is already saved. Keep the failure scoped to the\n                // optional driver-login setup instead of reporting a save error.\n                console.error(\"Driver login setup failed:\", error);\n                showToast(`Vehicle saved. Driver login setup pending: ${error.message || \"please try again.\"}`, \"info\");\n            }\n        }\n        if (trackingPending) {\n            showToast(\"Vehicle saved. Live tracking sync pending.\", \"info\");\n        }\n        resetForm(); await loadVehicles();\n    } catch(e) { console.error(e); alert(e.message || \"Failed to save vehicle.\"); }\r\n    finally { setButtonBusy(submitBtn, false); }\r\n});\r\n\r\nasync function loadVehicles() {\r\n    try {\r\n        if (vehicleListLoading) vehicleListEl.innerHTML = skeletonCards(4);\r\n        const snap = await getDocs(collection(db, \"schools\", adminId, \"vehicles\"));\r\n        vehicles = snap.docs.map(d => ({ id: d.id, ...d.data() }));\r\n        vehicleListLoading = false;\r\n        syncVehiclesForTracking();\r\n        filteredVehicles = [...vehicles];\r\n        updateStats(); renderVehicles();\r\n    } catch(e) { vehicleListLoading = false; vehicleListEl.innerHTML = '<div class=\"empty\">Failed to load records.</div>'; }\r\n}\r\n\r\nasync function syncVehiclesForTracking() {\r\n    Promise.all(vehicles.map(v => upsertVehicle(trackingVehiclePayload(v.id, v))\r\n        .catch(error => console.warn(\"Vehicle tracking sync failed\", v.id, error))));\r\n}\r\n\r\nfunction formatLiveAge(value) {\r\n    if (!value) return \"-\";\r\n    const seconds = Math.max(0, Math.round((Date.now() - new Date(value).getTime()) / 1000));\r\n    if (seconds < 60) return `${seconds}s ago`;\r\n    return `${Math.round(seconds / 60)}m ago`;\r\n}\r\n\r\nfunction queueLiveMapRefresh(repeats = 5, delay = 1800) {\r\n    window.clearTimeout(liveMapRefreshTimer);\r\n    const tick = async (left) => {\r\n        await refreshActiveTrips();\r\n        if (left > 1) liveMapRefreshTimer = window.setTimeout(() => tick(left - 1), delay);\r\n    };\r\n    liveMapRefreshTimer = window.setTimeout(() => tick(repeats), delay);\r\n}\r\n\r\nasync function refreshAdminLiveMap() {\r\n    const activeVehicleIds = activeTripRows.map(t => t.vehicle_id).filter(Boolean);\r\n    const vehicleIds = activeVehicleIds.length ? activeVehicleIds : vehicles.map(v => v.id);\r\n    const activeSet = new Set(activeVehicleIds);\r\n    liveLocationRows = await liveLocations(vehicleIds).catch(() => []);\r\n    if (activeSet.size) liveLocationRows = liveLocationRows.filter(loc => activeSet.has(loc.vehicle_id));\r\n    const byVehicle = new Map(vehicles.map(v => [v.id, v]));\r\n    const list = document.getElementById(\"adminLiveVehicleList\");\r\n    if (!list) return;\r\n    if (!liveLocationRows.length) {\r\n        if (activeSet.size) {\r\n            list.innerHTML = activeVehicleIds.map((vehicleId) => {\r\n                const v = byVehicle.get(vehicleId) || {};\r\n                return `<div class=\"live-vehicle-item is-waiting\">\r\n                    <strong>${escHtml(v.vehicleNumber || vehicleId)}</strong>\r\n                    <div>Driver: ${escHtml(v.driverName || \"-\")}</div>\r\n                    <div style=\"font-weight:800;color:#1d4ed8\">WAITING FOR FIRST GPS PING</div>\r\n                    <div>Driver app ko location permission ke saath logged in rakhein.</div>\r\n                </div>`;\r\n            }).join(\"\");\r\n        } else {\r\n            list.innerHTML = '<div class=\"empty\">No live GPS updates yet. Start tracking on a vehicle and keep the driver app logged in with location permission.</div>';\r\n        }\r\n        const heroLive = document.getElementById(\"heroLiveVehicles\");\r\n        if (heroLive) heroLive.textContent = \"0\";\r\n        clearMapMissing(adminMap, []);\r\n        return;\r\n    }\r\n    const heroLive = document.getElementById(\"heroLiveVehicles\");\r\n    if (heroLive) heroLive.textContent = String(liveLocationRows.length);\r\n    list.innerHTML = liveLocationRows.map(loc => {\r\n        const v = byVehicle.get(loc.vehicle_id) || {};\r\n        const status = locationStatus(loc.updated_at);\r\n        adminMap?.setVehicle(loc.vehicle_id, loc, v.vehicleNumber || v.vehicle_number || \"Vehicle\", {\r\n            driver: v.driverName || \"\",\r\n            route: v.routeName || \"\",\r\n            status\r\n        });\r\n        return `<div class=\"live-vehicle-item\">\r\n            <strong>${escHtml(v.vehicleNumber || loc.vehicle_id)}</strong>\r\n            <div>Driver: ${escHtml(v.driverName || \"-\")}</div>\r\n            <div style=\"font-weight:800;color:${status === \"live\" ? \"#16794f\" : \"#9a6700\"}\">${escHtml(status.toUpperCase())}</div>\r\n            <div>Updated: ${escHtml(formatLiveAge(loc.updated_at))}</div>\r\n            <div>Speed: ${escHtml(String(Math.round(calibratedSpeedKmh(loc.speed))))} km/h</div>\r\n            <div style=\"color:#64748b\">${escHtml(Number(loc.latitude).toFixed(5))}, ${escHtml(Number(loc.longitude).toFixed(5))}</div>\r\n        </div>`;\r\n    }).join(\"\");\r\n    clearMapMissing(adminMap, liveLocationRows.map(loc => loc.vehicle_id));\r\n    adminMap?.fitAll();\r\n}\r\n\r\nasync function refreshActiveTrips() {\r\n    activeTripRows = await activeTrips(vehicles.map(v => v.id)).catch(() => []);\r\n    renderVehicles();\r\n    await refreshAdminLiveMap();\r\n}\r\n\r\nfunction updateStats() {\r\n    document.getElementById(\"totalVehicles\").textContent     = vehicles.length;\r\n    document.getElementById(\"activeVehicles\").textContent    = vehicles.filter(v=>v.status===\"active\").length;\r\n    document.getElementById(\"maintenanceVehicles\").textContent = vehicles.filter(v=>v.status===\"maintenance\").length;\r\n    document.getElementById(\"inactiveVehicles\").textContent  = vehicles.filter(v=>v.status===\"inactive\").length;\r\n    document.getElementById(\"totalRoutes\").textContent       = routes.length;\r\n    const totalAssigned = vehicles.reduce((sum,v)=>sum+(Array.isArray(v.assignedStudentIds)?v.assignedStudentIds.length:0),0);\r\n    document.getElementById(\"totalAssigned\").textContent     = totalAssigned;\r\n    const heroActive = document.getElementById(\"heroActiveVehicles\");\r\n    const heroAssigned = document.getElementById(\"heroAssignedStudents\");\r\n    const heroRoutes = document.getElementById(\"heroSavedRoutes\");\r\n    if (heroActive) heroActive.textContent = String(vehicles.filter(v=>v.status===\"active\").length);\r\n    if (heroAssigned) heroAssigned.textContent = String(totalAssigned);\r\n    if (heroRoutes) heroRoutes.textContent = String(routes.length);\r\n}\r\n\r\nfunction statusBadge(s) {\r\n    if (s===\"active\")      return '<span class=\"pill active\">ACTIVE</span>';\r\n    if (s===\"maintenance\") return '<span class=\"pill maintenance\">MAINTENANCE</span>';\r\n    return '<span class=\"pill inactive\">INACTIVE</span>';\r\n}\r\n\r\nfunction formatVehicleRoute(v) {\r\n    const idPart = v.routeId ? `<span class=\"route-id-badge\" style=\"font-size:13px;\">${escHtml(v.routeId)}</span> ` : \"\";\r\n    if (v.routeFrom && v.routeTo) {\r\n        const via = Array.isArray(v.routeVia) ? v.routeVia : [];\r\n        const segs = [escHtml(v.routeFrom), ...via.map(s=>escHtml(s)), escHtml(v.routeTo)];\r\n        const extra = v.routeName && v.routeName!==`${v.routeFrom} - ${v.routeTo}` ? ` (${escHtml(v.routeName)})` : \"\";\r\n        return `${idPart}${segs.join(\" - \")}${extra}`;\r\n    }\r\n    return `${idPart}${escHtml(v.routeName||\"-\")}`;\r\n}\r\n\r\nfunction expiryWarning(dateStr) {\r\n    if (!dateStr) return \"\";\r\n    const d = new Date(dateStr);\r\n    const now = new Date();\r\n    const diff = Math.ceil((d - now) / (1000*60*60*24));\r\n    const alertIco = `<svg width=\"14\" height=\"14\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" style=\"vertical-align:-2px;margin-right:4px\" aria-hidden=\"true\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>`;\r\n    if (diff < 0) return `<span style=\"color:#dc2626;font-weight:700;display:inline-flex;align-items:center;\">${alertIco}Expired</span>`;\r\n    if (diff <= 30) return `<span style=\"color:#d97706;font-weight:700;display:inline-flex;align-items:center;\">${alertIco}Expiring in ${diff}d</span>`;\r\n    return \"\";\r\n}\r\n\r\nfunction renderVehicles() {\r\n    vehicleListEl.innerHTML = \"\";\r\n    if (!filteredVehicles.length) { vehicleListEl.innerHTML = '<div class=\"empty\">No vehicles found.</div>'; return; }\r\n    filteredVehicles.forEach(v => {\r\n        const row = document.createElement(\"div\");\r\n        const assigned = Array.isArray(v.assignedStudentIds) ? v.assignedStudentIds.length : 0;\r\n        const activeTrip = activeTripRows.find(t => t.vehicle_id === v.id);\r\n        const trackingOn = Boolean(activeTrip);\r\n        row.className = `vehicle-card ${trackingOn ? \"is-tracking\" : \"\"}`;\r\n        const compliance = `\r\n            Permit: ${escHtml(v.permitExpiry||\"-\")} ${expiryWarning(v.permitExpiry)}\r\n            &nbsp;|&nbsp; Insurance: ${escHtml(v.insuranceExpiry||\"-\")} ${expiryWarning(v.insuranceExpiry)}\r\n            &nbsp;|&nbsp; Fitness: ${escHtml(v.fitnessExpiry||\"-\")} ${expiryWarning(v.fitnessExpiry)}\r\n        `;\r\n        row.innerHTML = `\r\n            <div class=\"meta\">\r\n                <div class=\"vehicle-title\">\r\n                <strong>${escHtml(v.vehicleNumber || \"Vehicle\")}</strong>\r\n                ${statusBadge(v.status)}\r\n                <span class=\"pill ${trackingOn ? \"active\" : \"inactive\"}\">${trackingOn ? \"TRACKING ON\" : \"TRACKING OFF\"}</span>\r\n                <span class=\"students-count-badge\">${assigned} student${assigned!==1?\"s\":\"\"}</span>\r\n                </div>\r\n                <div class=\"vehicle-meta-grid\">\r\n                    <div class=\"vehicle-meta-box\"><small>Vehicle</small><span>${escHtml(v.vehicleType || \"-\")} ${v.vehicleModel ? `- ${escHtml(v.vehicleModel)}` : \"\"}</span></div>\r\n                    <div class=\"vehicle-meta-box\"><small>Capacity</small><span>${escHtml(String(v.capacity || 0))} seats</span></div>\r\n                    <div class=\"vehicle-meta-box\"><small>Driver</small><span>${escHtml(v.driverName || \"-\")} ${v.driverPhone ? `- ${escHtml(v.driverPhone)}` : \"\"}</span></div>\r\n                    <div class=\"vehicle-meta-box\"><small>Driver Login</small><span>${escHtml(v.driverEmail || \"Not set\")}</span></div>\r\n                    <div class=\"vehicle-meta-box\" style=\"grid-column: span 2;\"><small>Route</small><span>${formatVehicleRoute(v)}</span></div>\r\n                    <div class=\"vehicle-compliance\">${compliance}</div>\r\n                    ${v.notes ? `<div class=\"vehicle-meta-box\" style=\"grid-column:1/-1;\"><small>Notes</small><span>${escHtml(v.notes)}</span></div>` : \"\"}\r\n                </div>\r\n            </div>\r\n            <div class=\"action-col\">\r\n                ${trackingOn\r\n                    ? `<button class=\"btn-danger\" onclick=\"stopVehicleTracking('${escHtml(v.id)}')\">${ICONS.stop}Stop Tracking</button>`\r\n                    : `<button class=\"btn-primary\" onclick=\"startVehicleTracking('${escHtml(v.id)}')\">${ICONS.play}Start Tracking</button>`}\r\n                <button class=\"btn-purple\" onclick=\"openAssignModal('${escHtml(v.id)}')\">${ICONS.users}Assign Students</button>\r\n                <button class=\"btn-success\" onclick=\"editVehicle('${escHtml(v.id)}')\">${ICONS.edit}Edit</button>\r\n                <button class=\"btn-danger\"  onclick=\"deleteVehicle('${escHtml(v.id)}')\">${ICONS.trash}Delete</button>\r\n            </div>`;\r\n        vehicleListEl.appendChild(row);\r\n    });\r\n}\r\n\r\nwindow.startVehicleTracking = async (vehicleId) => {\r\n    const v = vehicles.find(x => x.id === vehicleId);\r\n    if (!v) return;\r\n    const actionButton = currentActionButton();\r\n    if (!confirm(`Start tracking for ${v.vehicleNumber || vehicleId}? Driver phone will begin sending GPS if logged in and permission is granted.`)) return;\r\n    try {\r\n        setButtonBusy(actionButton, true, \"Starting...\");\r\n        setPageBusy(true, \"Starting tracking...\", \"Opening active trip and preparing live GPS sync.\");\r\n        const synced = await safeUpsertTrackingVehicle(vehicleId, v);\r\n        if (!synced) {\r\n            alert(\"Live tracking sync complete nahi ho paaya. Vehicle save karke dobara Start Tracking try karo.\");\r\n            return;\r\n        }\r\n        await startTrip(vehicleId);\r\n        showToast(\"Tracking started. Admin map is watching for the driver's live GPS now.\", \"success\");\r\n        await refreshActiveTrips();\r\n        await refreshAdminLiveMap();\r\n        queueLiveMapRefresh();\r\n    } catch (error) {\r\n        console.error(error);\r\n        if (isTransportSetupMissing(error)) {\r\n            alert(\"Supabase transport migration apply nahi hui hai. Transport tables/RPC missing hain, isliye Start Tracking nahi chal sakta.\");\r\n        } else if (isTransportAccessDenied(error)) {\r\n            alert(\"Live tracking access denied hai. Admin account se dobara login karo, phir Start Tracking try karo.\");\r\n        } else {\r\n            alert(error.message || \"Could not start tracking. Vehicle/driver sync check karke dobara try karo.\");\r\n        }\r\n    } finally {\r\n        setButtonBusy(actionButton, false);\r\n        setPageBusy(false);\r\n    }\r\n};\r\n\r\nwindow.stopVehicleTracking = async (vehicleId) => {\r\n    const v = vehicles.find(x => x.id === vehicleId);\r\n    if (!v) return;\r\n    const actionButton = currentActionButton();\r\n    if (!confirm(`Stop tracking for ${v.vehicleNumber || vehicleId}?`)) return;\r\n    try {\r\n        setButtonBusy(actionButton, true, \"Stopping...\");\r\n        setPageBusy(true, \"Stopping tracking...\", \"Closing active trip for this vehicle.\");\r\n        await stopTrip(vehicleId);\r\n        showToast(\"Tracking stopped.\", \"success\");\r\n        await refreshActiveTrips();\r\n        await refreshAdminLiveMap();\r\n    } catch (error) {\r\n        console.error(error);\r\n        alert(error.message || \"Could not stop tracking.\");\r\n    } finally {\r\n        setButtonBusy(actionButton, false);\r\n        setPageBusy(false);\r\n    }\r\n};\r\n\r\nfunction applyFilters() {\r\n    const q = searchInput.value.trim().toLowerCase();\r\n    const s = statusFilter.value, t = typeFilter.value;\r\n    filteredVehicles = vehicles.filter(v => {\r\n        const viaMatch = (Array.isArray(v.routeVia)?v.routeVia:[]).some(x=>(x||\"\").toLowerCase().includes(q));\r\n        const matchQ =\r\n            (v.vehicleNumber||\"\").toLowerCase().includes(q) ||\r\n            (v.routeName||\"\").toLowerCase().includes(q) ||\r\n            (v.routeId||\"\").toLowerCase().includes(q) ||\r\n            (v.routeFrom||\"\").toLowerCase().includes(q) ||\r\n            (v.routeTo||\"\").toLowerCase().includes(q) || viaMatch ||\r\n            (v.driverName||\"\").toLowerCase().includes(q) ||\r\n            (v.driverPhone||\"\").toLowerCase().includes(q) ||\r\n            (v.driverEmail||\"\").toLowerCase().includes(q);\r\n        return matchQ && (s===\"all\"||v.status===s) && (t===\"all\"||v.vehicleType===t);\r\n    });\r\n    renderVehicles();\r\n}\r\nsearchInput.addEventListener(\"input\", applyFilters);\r\nstatusFilter.addEventListener(\"change\", applyFilters);\r\ntypeFilter.addEventListener(\"change\", applyFilters);\r\n\r\nwindow.editVehicle = (id) => {\r\n    const v = vehicles.find(x => x.id===id); if (!v) return;\r\n    editingVehicleId = id;\r\n    document.getElementById(\"vehicleNumber\").value   = v.vehicleNumber||\"\";\r\n    document.getElementById(\"vehicleType\").value     = v.vehicleType||\"\";\r\n    document.getElementById(\"vehicleModel\").value    = v.vehicleModel||\"\";\r\n    document.getElementById(\"capacity\").value        = v.capacity||\"\";\r\n    document.getElementById(\"driverName\").value      = v.driverName||\"\";\r\n    document.getElementById(\"driverPhone\").value     = v.driverPhone||\"\";\r\n    document.getElementById(\"driverEmail\").value     = v.driverEmail||\"\";\r\n    document.getElementById(\"driverPassword\").value  = \"\";\r\n    populateRouteDropdown(); vehicleRouteSelect.value = v.routeId||\"\";\r\n    document.getElementById(\"routeName\").value       = v.routeName||\"\";\r\n    document.getElementById(\"permitExpiry\").value    = v.permitExpiry||\"\";\r\n    document.getElementById(\"insuranceExpiry\").value = v.insuranceExpiry||\"\";\r\n    document.getElementById(\"fitnessExpiry\").value   = v.fitnessExpiry||\"\";\r\n    document.getElementById(\"vehicleStatus\").value   = v.status||\"active\";\r\n    document.getElementById(\"notes\").value           = v.notes||\"\";\r\n    formTitleEl.textContent = \"Edit Vehicle\";\r\n    saveBtnEl.innerHTML     = saveVehicleButtonHtml(\"Update Vehicle\");\r\n    window.scrollTo({ top: 0, behavior: \"smooth\" });\r\n};\r\n\r\nwindow.deleteVehicle = async (id) => {\r\n    const actionButton = currentActionButton();\r\n    if (!confirm(\"Delete this vehicle?\")) return;\r\n    try {\r\n        setButtonBusy(actionButton, true, \"Deleting...\");\r\n        setPageBusy(true, \"Deleting vehicle...\", \"Removing record and refreshing transport workspace.\");\r\n        await deleteDoc(doc(db, \"schools\", adminId, \"vehicles\", id));\r\n        if (editingVehicleId===id) resetForm();\r\n        await loadVehicles();\r\n        showToast(\"Vehicle deleted.\", \"info\");\r\n    } catch(e) { alert(\"Failed to delete.\"); }\r\n    finally {\r\n        setButtonBusy(actionButton, false);\r\n        setPageBusy(false);\r\n    }\r\n};\r\n\r\nwindow.resetForm = () => {\r\n    editingVehicleId = null; vehicleForm.reset();\r\n    document.getElementById(\"driverPassword\").value = \"\";\r\n    document.getElementById(\"vehicleStatus\").value = \"active\";\r\n    vehicleRouteSelect.value = \"\"; populateRouteDropdown();\r\n    formTitleEl.textContent = \"Add Vehicle\"; saveBtnEl.innerHTML = saveVehicleButtonHtml(\"Save Vehicle\");\r\n};\r\n\r\nwindow.logout = async () => {\r\n    try { await signOut(auth); window.location.href = \"#/index.html\"; }\r\n    catch(e) { alert(\"Logout failed.\"); }\r\n};\r\n\r\ndocument.getElementById(\"studentSearchInput\").addEventListener(\"keydown\", e => {\r\n    if (e.key === \"Enter\") { e.preventDefault(); searchStudents(); }\r\n});\r\nrouteLookupInput.addEventListener(\"keydown\", e => {\r\n    if (e.key === \"Enter\") { e.preventDefault(); fetchRouteById(); }\r\n});\r\n"},{"attributes":{"type":"module","src":"access-control.js"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""},{"attributes":{"src":"admin-shell.js?v=navbar-20260721"},"text":""}]};
